// Üretilen dosya: tool/ozgun/uret.py. Müzik · Orta Çağ, Rönesans ve Barok müziği: formlar, çalgılar ve besteciler (madrigal, füg, konçerto grosso, oratoryo, klavsen, Vivaldi, Bach, Handel, Monteverdi) (orta).
const ozMusic15Orta = <(String, String, List<String>, String)>[
  ('Gregoryen ezgilerinde tek bir metin hecesinin çok sayıda nota boyunca uzatılarak süslü biçimde seslendirilmesine hangi terim karşılık gelir?', 'Melismatik üslup', ['Silabik söyleme tarzı', 'Resitatif konuşma düzeni', 'İzoritmik tekrar kurgusu'], 'Bir heceye tek nota düşmesine silabik, iki-dört nota düşmesine nömatik, çok sayıda nota düşerek uzun ezgisel kıvrımlar oluşmasına ise melismatik üslup denir.'),
  ('Orta Çağ ayinlerinde iki ayrı koronun mezmur dizelerini karşılıklı nöbetleşe seslendirmesi hangi icra biçimi olarak adlandırılır?', 'Antifonal söyleme', ['Responsorial seslendirme', 'Polikoral kanonik giriş', 'Heterofonik çeşitleme'], 'İki koronun sırayla söylemesine antifonal icra, bir solistin okuyup koronun yanıt vermesine ise responsorial icra adı verilir.'),
  ('Notre Dame okulunda kilise takviminin önemli yortuları için bestelenen çoksesli ezgileri bir araya getiren \'Magnus Liber Organi\' derlemesi kime atfedilir?', 'Usta Léonin\'e', ['Philippe de Vitry\'ye', 'Guillaume de Machaut\'ya', 'Johannes Tinctoris\'e'], 'Anonim IV adlı kuramcının aktarımına göre \'Organumun Büyük Kitabı\' anlamına gelen Magnus Liber Organi, Notre Dame Katedrali için Léonin tarafından hazırlanmıştır.'),
  ('Pérotin\'in \'Viderunt omnes\' ve \'Sederunt principes\' adlı eserleri, Batı müzik tarihinde hangi yeniliğin simgesi sayılır?', 'Dört sesli çoksesli (organum quadruplum) yazının olgunlaşmasının', ['Din dışı Fransızca aşk şarkılarının kiliseye girmesinin', 'Majör ve minör ton sisteminin resmen kabul edilmesinin', 'Yaylı çalgılar dörtlüsü için ilk bağımsız bölümün yazılmasının'], 'Pérotin, Gregoryen ezgisinin üzerine üç bağımsız üst ses ekleyerek dört sesli \'organum quadruplum\' dokusunu anıtsal boyutlara taşımıştır.'),
  ('Erken dönem paralel organum uygulamalarında ana Gregoryen ezgisinin (vox principalis) altına eklenen ikinci ses genellikle hangi aralıklarla hareket ederdi?', 'Tam dörtlü ve tam beşli aralıklarıyla', ['Büyük üçlü ve küçük altılı aralıklarıyla', 'Büyük yedili ve eksiltilmiş beşli aralıklarıyla', 'Yarım tonluk kromatik ikili yürüyüşlerle'], '9. yüzyıldaki \'Musica enchiriadis\' incelemesinde tanımlanan erken organumda, konsonans kabul edilen oktav, tam beşli ve tam dörtlü aralıklarıyla paralel hareket esastı.'),
  ('Notre Dame çoksesliliğinde nota sürelerini ilk kez sistematik kalıplara bağlayan \'ritmik modlar\' sisteminde temel ölçü birimi kaçlı bölünmeye dayanıyordu?', 'Teslis inancını simgeleyen üçlü bölünmeye', ['Yürüyüş temposunu yansıtan ikili bölünmeye', 'Halk danslarından alınan aksak yedi zamanlı kalıplara', 'Nefes uzunluğuna göre değişen serbest ölçü yapısına'], 'Orta Çağ\'da üçlü zaman (tempus perfectum) Kutsal Üçleme\'yi simgelediği için kusursuz kabul edilmiş ve Notre Dame\'ın altı ritmik modu üçlü birim üzerine kurulmuştur.'),
  ('13. yüzyıl sonlarında tek bir eserde üst seslerin biri Fransızca aşk şiiri, diğeri Latince Meryem Ana övgüsü söylerken en alt sesin ayin ezgisi çaldığı tür hangisidir?', 'Çok metinli (politekstüel) Ars Antiqua moteti', ['İtalyan Trecento dönemi pastoral madrigali', 'Alman Minnesänger geleneğinin Bar formu', 'Gregoryen ayininin Kyrie eleison bölümü'], 'Ars Antiqua dönemi motetlerinde farklı dillerde ve konularda metinlerin aynı anda üst üste duyurulması (politekstüalite) dönemin karakteristik özelliğidir.'),
  ('14. yüzyıl Fransız müziğine adını veren ve ikili zaman bölünmesini üçlü zamanla eşit statüye kavuşturan \'Ars Nova\' incelemesinin yazarı kimdir?', 'Philippe de Vitry', ['Adam de la Halle', 'Bernart de Ventadorn', 'Johannes Ockeghem'], 'Fransız besteci ve kuramcı Philippe de Vitry, yaklaşık 1320\'de kaleme aldığı \'Ars Nova\' (Yeni Sanat) adlı kuramsal çalışmasıyla 14. yüzyıl ritmik devrimini sistemleştirmiştir.'),
  ('Ars Nova motetlerinde tenor partisinin ritmik kalıbı ile ezgisel dizisinin farklı uzunluklarda tekrarlanmasına dayanan yapısal tekniğe ne ad verilir?', 'İzoritim', ['Fauxbourdon', 'Basso ostinato', 'Heterofoni'], 'İzoritmik yapıda tekrarlanan ritmik kalıba \'talea\', tekrarlanan ses yükseklikleri dizisine ise \'color\' denir; bu iki döngünün çakışmaması karmaşık bir mimari kurar.'),
  ('Katolik Missa ayininin yıl boyunca her törende metni değişmeden kalan \'Ordinarium\' (Olağan) bölümleri arasında aşağıdakilerden hangisi yer almaz?', 'Alleluia', ['Kyrie', 'Sanctus', 'Agnus Dei'], 'Kyrie, Gloria, Credo, Sanctus ve Agnus Dei ayinin değişmez (Ordinarium) bölümleridir; Introitus, Graduale ve Alleluia ise güne göre değişen (Proprium) bölümlerdir.'),
  ('14. ve 15. yüzyıl Fransız dünyevi şarkılarında şiir ve müzik tekrarlarının sıkı kurallara bağlandığı \'formes fixes\' (sabit biçimler) üçlüsü hangisidir?', 'Ballade, rondeau ve virelai', ['Allemande, courante ve sarabande', 'Toccata, ricercar ve canzona', 'Frottola, villanella ve lauda'], 'Orta Çağ sonu Fransız şair-bestecilerinin dünyevi şansonlarda kullandığı üç temel sabit şiir-müzik kalıbı ballade, rondeau ve virelai\'dir.'),
  ('Güney Fransa\'daki troubadour geleneği içinde eser veren kadın şair-bestecileri tanımlamak için hangi tarihsel terim kullanılır?', 'Trobairitz', ['Jongleuse', 'Minnesängerin', 'Concerto delle donne'], 'Beatriz de Dia (Comtessa de Dia) gibi soylu kadın ozanlar Oksitan kültüründe \'trobairitz\' olarak adlandırılmış ve kadın bakış açısıyla saray aşkı şiirleri bestelemişlerdir.'),
  ('Kuzey Fransa trouvère geleneğinin son büyük temsilcilerinden olup \'Jeu de Robin et de Marion\' adlı müzikli pastoral oyunu besteleyen sanatçı kimdir?', 'Adam de la Halle', ['Bernart de Ventadorn', 'Walther von der Vogelweide', 'Oswald von Wolkenstein'], 'Adam de la Halle, hem çoksesli rondeau\'lar hem de din dışı müzikli tiyatronun öncüsü kabul edilen \'Jeu de Robin et de Marion\'u (yaklaşık 1283) yazmıştır.'),
  ('Alman Minnesänger şarkılarında iki özdeş ezgisel kıta (Stollen) ve bunları izleyen farklı bir sonuç kesitinden (Abgesang) oluşan AAB biçimine ne ad verilir?', 'Bar formu', ['Ritornello formu', 'Da capo arya kalıbı', 'Sonat allegrosu'], 'AAB şemasına sahip \'Bar formu\', Orta Çağ Alman Minnesänger ve sonraki Meistersinger lonca şarkılarının en temel biçimsel iskeletidir.'),
  ('13. yüzyıl İspanya\'sında Kastilya Kralı Bilge X. Alfonso\'nun himayesinde Galiçya-Portekiz dilinde hazırlanan ve Meryem Ana mucizelerini anlatan 400\'ü aşkın şarkılık derleme hangisidir?', 'Cantigas de Santa Maria', ['Llibre Vermell de Montserrat', 'Cancionero de Palacio', 'Ordo Virtutum'], 'Cantigas de Santa Maria, hem zengin tek sesli ezgileri hem de Orta Çağ İslam ve Hristiyan çalgıcılarını bir arada betimleyen minyatürleriyle eşsiz bir kaynaktır.'),
  ('14. yüzyıl İtalyan müziğini ifade eden \'Trecento\' döneminin en ünlü bestecisi, görme engelli Floransalı org virtüözü kimdir?', 'Francesco Landini', ['Jacopo Peri', 'Claudio Monteverdi', 'Arcangelo Corelli'], 'Küçük yaşta çiçek hastalığından görme yetisini yitiren Francesco Landini, portatif orgdaki ustalığı ve dünyevi ballata\'larıyla İtalyan Trecento müziğinin zirvesidir.'),
  ('14. yüzyıl İtalyan Trecento repertuvarında av sahnelerini, pazar yeri bağrışmalarını ve doğa seslerini iki üst sesin sıkı kanonuyla canlandıran vokal form hangisidir?', 'Caccia', ['Pavane', 'Ricercar', 'Passacaglia'], 'İtalyancada \'av\' anlamına gelen caccia, iki sesin birbirini kanon halinde kovaladığı, altında ise çalgısal bir tenor partisinin yer aldığı canlı betimleyici bir formdur.'),
  ('6. yüzyılda kaleme aldığı \'De institutione musica\' adlı eseriyle müziği kozmik uyum (musica mundana), insan uyumu (musica humana) ve çalgısal ses (musica instrumentalis) olarak üçe ayıran düşünür kimdir?', 'Boethius', ['Aziz Augustinus', 'Aquinolu Thomas', 'Desiderius Erasmus'], 'Romalı filozof Boethius, Antik Yunan müzik kuramını Orta Çağ Batı dünyasına aktaran en temel otorite olmuş ve müziği matematiksel oranlar bilimi olarak sınıflandırmıştır.'),
  ('Orta Çağ üniversitelerinin yedi özgür sanatı içinde müziğin aritmetik, geometri ve astronomi ile birlikte yer aldığı dörtlü bilim kümesine ne ad verilirdi?', 'Quadrivium', ['Trivium', 'Studia humanitatis', 'Camerata'], 'Orta Çağ eğitiminde gramer, retorik ve mantık sözel üçlüyü (Trivium); aritmetik, geometri, astronomi ve müzik ise sayısal dörtlüyü (Quadrivium) oluştururdu.'),
  ('Beyaz tuşlar üzerinde Re notasından başlayıp bir oktav tizdeki Re\'ye kadar hiçbir değiştirici işaret almadan çıkan kilise modu hangisidir?', 'Dorian', ['Phrygian', 'Lydian', 'Mixolydian'], 'Orta Çağ mod sisteminde birinci autentik mod olan Dorian Re–Re, Phrygian Mi–Mi, Lydian Fa–Fa, Mixolydian ise Sol–Sol dizisine karşılık gelir.'),
  ('Orta Çağ müzik kuramında \'musica ficta\' kavramı, icracıların dizekte yazılı olmayan değiştirici işaretleri özellikle hangi aralığın tınlamasını önlemek için eklemesini ifade eder?', 'Müzikte şeytan (diabolus in musica) sayılan artmış dörtlü / tritonus aralığını', ['Açık tınladığı düşünülen tam beşli konsonans aralığını', 'İki sesin aynı perdede birleştiği ünison tınısını', 'Sekizli aralığında paralel yürüyen oktav katlamasını'], 'Fa ile Si arasındaki tritonus (üç tam seslik aralık) sert ve uyumsuz bulunduğundan, şarkıcılar doğaçlama olarak Si notasını bemolleştirerek (Si bemol) bu aralıktan kaçınırdı.'),
  ('Arezzolu Guido ile ilişkilendirilen \'Guido Eli\' (Manus Guidonis) pedagojik aracının Orta Çağ koro eğitimindeki işlevi neydi?', 'Parmak eklemlerine atanan notaları işaret ederek şarkıcılara deşifraj yaptırmak', ['Vuruş hızını el çırparak ölçüp orkestra şefliği görevini yürütmek', 'Sağır keşişlerle sessiz işaret dili aracılığıyla felsefi iletişim kurmak', 'Çalgı tellerinin uzunluk oranlarını avuç genişliğiyle hesaplamak'], 'Koro şefi sol elinin boğum ve uçlarına yerleştirilmiş yirmi nota basamağını sağ eliyle göstererek koro üyelerinin yeni ezgileri hızla öğrenmesini sağlardı.'),
  ('Yaklaşık 1250 yılından kalma, altı erkek sesinin baharın gelişini neşeyle söylediği ve Batı müziğinin en eski çoksesli dairesel kanon (rota) örneği sayılan İngiliz eseri hangisidir?', 'Sumer is icumen in', ['Greensleeves', 'Agincourt İlahisi', 'Flow my tears'], 'Reading Manastırı kaynaklı Orta İngilizce \'Sumer is icumen in\' (Yaz geliyor), iki bas sesin pes bir ostinato (pes) tekrarladığı, dört üst sesin ise kanon yaptığı eşsiz bir eserdir.'),
  ('İslam dünyasındaki rebaptan Avrupa\'ya geçen, yarım armut biçimli gövdesi tek parça ağaçtan oyulan üç telli tiz sesli Orta Çağ yaylı çalgısı hangisidir?', 'Rebec', ['Theorbo', 'Klavikord', 'Dulcian'], 'Endülüs ve Haçlı seferleri aracılığıyla Avrupa\'ya yayılan rebec, armudi gövdesi ve parlak tiz sesiyle Orta Çağ dans ve şölen müziğinde yaygın biçimde kullanılmıştır.'),
  ('Orta Çağ\'da telleri yay yerine reçineli ahşap bir çarkın kolla çevrilmesiyle titreştirilen, tuşlarla ezgi çalınırken burdon tellerinin sürekli dem tuttuğu çalgı hangisidir?', 'Organistrum', ['Psalterium', 'Çembalo', 'Krummhorn'], 'Erken dönemde iki kişinin çaldığı büyük kilise çalgısı \'organistrum\', daha sonra tek gezgin çalgıcının taşıyabildiği \'vielle à roue\' (hurdy-gurdy) biçimine dönüşmüştür.'),
  ('Yamuk veya dikdörtgen ses kutusu üzerine gerilmiş tellerin parmakla ya da tüy mızrapla çekilerek çalındığı, kanuna benzeyen Orta Çağ çalgısı hangisidir?', 'Psalterium', ['Şalümo', 'Kornetto', 'Serpent'], 'Psalterium telleri çekilerek çalınan bir kutu zither\'dir; benzer gövdedeki tellere küçük tokmaklarla vurularak çalınan türüne ise \'dulcimer\' (santur türevi) denir.'),
  ('Çift kamışlı konik gövdesiyle keskin ve gür bir ses çıkaran, modern obuanın Orta Çağ ve Rönesans\'taki açık hava öncüsü olan üflemeli çalgı hangisidir?', 'Şalümo', ['Travers flüt', 'Panflüt', 'Basset korno'], 'İslam dünyasındaki zurnadan etkilenerek gelişen shawm (Almanca Schalmei/Pommer), törenlerde ve kule müziğinde kullanılan güçlü çift kamışlı çalgıdır.'),
  ('Orta Çağ manastır yaşamında rahiplerin gece yarısından yatma vaktine kadar günün belirli sekiz saatinde topluca söyledikleri dua ve mezmur törenlerine ne ad verilir?', 'Saatler Litürjisi', ['Kutsal Efkaristiya Missası', 'Paskalya Arifesi Vigili', 'Tridentinum Konsili Kararları'], 'Matins, Lauds, Vespers ve Compline gibi sekiz ibadet vaktinden oluşan günlük dua döngüsü \'Officium Divinum\' (İlahi Görev / Saatler Litürjisi) olarak adlandırılır.'),
  ('Saatler Litürjisi\'nin gün batımında gerçekleştirilen, müzik tarihinde \'Magnificat\' ilahisinin seslendirilmesiyle öne çıkan akşam ibadeti hangisidir?', 'Vespers (Akşam Duası)', ['Matins (Gece Duası)', 'Terce (Kuşluk Duası)', 'Prime (Sabah İlk Saat)'], 'Vespers, gün batımı töreni olup Meryem Ana\'nın şükran ilahisi \'Magnificat\'ı içermesi nedeniyle Orta Çağ\'dan Barok döneme dek çoksesli müzik için en verimli saat ibadeti olmuştur.'),
  ('Orta Çağ dans formlarında bir bölmenin ilk çalışta kararsız bir seste bitmesini, ikinci tekrarında ise eksen seste karar kılmasını belirten terim çifti hangisidir?', 'Ouvert ve clos', ['Dux ve comes', 'Tonic ve dominant', 'Ripieno ve soli'], 'Modern notasyondaki 1. ve 2. dolapların (prima/seconda volta) öncüsü olan bu yapıda ilk yarım bitişe \'ouvert\' (açık), ikinci tam bitişe \'clos\' (kapalı) denirdi.'),
  ('Aslan Yürekli İngiltere Kralı I. Richard\'ın Haçlı Seferi dönüşü esir düştüğü kalede yazdığı \'Ja nus hons pris\' adlı eseri hangi müzik geleneğine aittir?', 'Trouvère şarkı geleneğine', ['Gregoryen mezmur okumalarına', 'İngiliz madrigal okuluna', 'Alman koral ilahi dağarcığına'], 'Fransız soylu kültürüyle yetişen ve Akitanyalı Eleanor\'un oğlu olan I. Richard, esareti sırasında dostlarından yardım isteyen ünlü bir trouvère şarkısı (rotrouenge) yazmıştır.'),
  ('Papa XXII. Ioannes\'in 1324\'te Avignon\'da yayımladığı \'Docta Sanctorum Patrum\' kararnamesiyle kilise müziğinde eleştirip yasaklamaya çalıştığı yenilik neydi?', 'Ars Nova\'nın hızlı notaları, hocket kesintileri ve dünyevi ezgi karmaşası', ['Kadın rahibelerin manastır içinde tek sesli ilahi söylemesi', 'Dört çizgili dizek üzerinde kare nota başlarının kullanılması', 'Mezmurların İbranice yerine Latince tercümesiyle okunması'], 'Papa XXII. Ioannes, Ars Nova bestecilerinin aşırı karmaşık ritimlerinin ve hocket tekniğinin kutsal metnin anlaşılmasını engellediğini savunarak muhafazakâr bir tepki göstermiştir.'),
  ('Orta Çağ çoksesliliğinde alt partide uzun notalarla tutulan temel ezgiye \'tenor\' adının verilmesinin etimolojik nedeni nedir?', 'Latince \'tenere\' (tutmak) fiilinden gelip ana ezgiyi taşıyan parti olması', ['Yalnızca on yaşındaki erkek çocukların ses aralığına uygun yazılması', 'Sahnede on adım önde duran baş şarkıcı tarafından okunması', 'Korno benzeri metal bir boruyla seslendirilen çalgı partisi olması'], 'Latince \'tenere\' (tutmak/sürdürmek) sözcüğünden türeyen tenor, başlangıçta ses rengini değil, Gregoryen cantus firmus\'u uzun değerlerle tutan temel partiyi ifade ediyordu.'),
  ('15. yüzyıl başında İngiliz müziğinin üçlü ve altılı aralıkların tatlı tınısına dayanan üslubunu (\'contenance angloise\') kıta Avrupası\'na tanıtan en önemli besteci kimdir?', 'John Dunstable', ['Henry Purcell', 'John Dowland', 'Orlando Gibbons'], 'Geç Orta Çağ\'dan Rönesans\'a geçişte John Dunstable, tam dörtlü ve beşlilerin sert tınısı yerine üçlü ve altılı konsonanslarını öne çıkararak Burgondiya okulunu derinden etkilemiştir.'),
  ('Orta Çağ\'da gezgin ozanların ölen bir hükümdarın, şövalyenin ya da koruyucu soylunun ardından duydukları derin kederi dile getirdikleri ağıt şarkılarına ne ad verilirdi?', 'Planctus (Planh)', ['Alba (Şafak şarkısı)', 'Pastourelle', 'Chanson de toile'], 'Latincede \'planctus\', Oksitancada \'planh\' olarak bilinen tür, Orta Çağ\'da önemli kişilerin ölümü üzerine yakılan soylu ağıt şarkısıdır.'),
  ('Troubadour şiir ve müziğinde gizlice buluşan iki sevgiliyi sabahın sökmesiyle uyaran gözcü arkadaş temasını işleyen şarkı türü hangisidir?', 'Alba (Şafak şarkısı)', ['Sirventes (Siyasi taşlama)', 'Jeu-parti (Münazara şarkısı)', 'Crusade song (Haçlı ezgisi)'], 'Oksitanca \'şafak\' anlamına gelen \'alba\' (Fransızca aubade, Almanca Tagelied), gün doğumunda ayrılmak zorunda kalan sevgililerin hüznünü anlatır.'),
  ('Roland Destanı gibi kahramanlık öykülerinin jongleur\'ler tarafından vielle eşliğinde binlerce dize boyunca basit tekrarlı ezgi formülleriyle anlatıldığı epik tür hangisidir?', 'Chanson de geste', ['Frottola', 'Madrigal komedisi', 'Virelai'], '\'Kahramanlık edimleri şarkısı\' anlamına gelen chanson de geste, Orta Çağ Fransa\'sında Şarlman ve şövalyelerinin destanlarını ezgili biçimde aktaran sözlü-müzikal gelenektir.'),
  ('Alman Minnesänger şair ve müzisyenlerinin şövalye armalarıyla süslü portrelerini ve şiirlerini günümüze ulaştıran 14. yüzyıl Zürih kaynaklı ünlü el yazması hangisidir?', 'Codex Manesse', ['Winchester Troper', 'Robertsbridge Kodeksi', 'Cancionero de Upsala'], 'Büyük Heidelberg Şarkı El Yazması olarak da bilinen Codex Manesse, 130\'dan fazla Minnesänger\'in tam sayfa minyatürlerini ve şiir metinlerini barındırır.'),
  ('9. yüzyılda Konstantinopolis\'te yaşamış, elliden fazla Bizans ilahisi günümüze ulaşan ve müzik tarihinin eserleri korunmuş en eski kadın bestecilerinden sayılan başrahibe kimdir?', 'Kassia', ['Sappho', 'Barbara Strozzi', 'Élisabeth Jacquet de La Guerre'], 'Bizanslı şair ve besteci Başrahibe Kassia (yaklaşık 810–865), özellikle Büyük Çarşamba günü hâlâ seslendirilen \'Kassia İlahisi\' (Troparion) ile tanınır.'),
  ('Orta Çağ dizek yazısında solfej hecelerinden \'ut\' notasının yüzyıllar içinde \'do\' hecesiyle değiştirilmesinin temel gerekçesi aşağıdakilerden hangisidir?', 'Açık ünlüyle biten \'do\' hecesinin şan eğitiminde çok daha rahat seslendirilmesi', ['Fransız Devrimi sonrasında Latince kökenli tüm nota adlarının yasaklanması', 'Kilisenin \'ut\' hecesini putperest büyü sözcüğü sayarak aforoz etmesi', 'Piyanonun icadıyla birlikte dizekteki çizgi sayısının dörtten altıya çıkarılması'], '17. yüzyılda İtalyan müzikolog Giovanni Battista Doni, kapalı \'t\' ünsüzüyle biten \'ut\' hecesinin şarkı söylerken tınıyı boğduğunu belirterek kendi soyadının ilk hecesi ve \'Dominus\' çağrışımlı açık \'do\' hecesini önermiştir.'),
  ('Orta Çağ notasyonunda yedinci derece olan \'si\' hecesi Arezzolu Guido\'nun ilk altı heceli sisteminde (heksakord) bulunmuyordu; bu hece sonradan hangi kelimelerin baş harflerinden türetilmiştir?', 'Sancte Ioannes', ['Soli Deo', 'Semper Idem', 'Sursum Corda'], '\'Ut queant laxis\' ilahisinin ilk kıtasının son dizesi olan \'Sancte Ioannes\' (Aziz Yahya) sözcüklerinin baş harfleri olan S ve I birleştirilerek yedinci dereceye \'si\' adı verilmiştir.'),
  ('10. yüzyılda İngiltere\'deki Winchester Katedrali için inşa edilen ve yetmiş kişinin çalıştırdığı yirmi altı körüğüyle kentin her yerinden duyulduğu anlatılan dev çalgı neydi?', 'Dört yüz borulu erken Orta Çağ kilise orgu', ['Dev bronz çanlardan kurulu kule karilyonu', 'Su basıncıyla çalışan Roma amfitiyatro hidraulisi', 'Yüz telli dev katedral arpi'], 'Rahip Wulfstan\'ın şiirinde ayrıntılarıyla betimlediği 10. yüzyıl Winchester orgu, Orta Çağ\'da mekanik kilise orgunun ulaştığı şaşırtıcı büyüklüğün en ünlü belgesidir.'),
  ('1501 yılında Venedik\'te hareketli metal harf kalıplarıyla tarihin ilk çoksesli müzik kitabı \'Harmonice Musices Odhecaton\'u basan matbaacı kimdir?', 'Ottaviano Petrucci', ['Johannes Gutenberg', 'Antonio Stradivari', 'Lorenzo de\' Medici'], 'Ottaviano Petrucci, dizek çizgilerini, notaları ve metni üç ayrı baskı aşamasıyla basarak 1501\'de müzik yayıncılığında devrim yaratmıştır.'),
  ('Martin Luther\'in \'Notaların efendisi odur, diğer besteciler ise notaların ne isterse onu yapar\' sözleriyle övdüğü Yüksek Rönesans ustası kimdir?', 'Josquin des Prez', ['Claudio Monteverdi', 'Carlo Gesualdo', 'Andrea Gabrieli'], 'Franko-Flaman besteci Josquin des Prez (yaklaşık 1450–1521), kusursuz kontrpuan tekniğini insani duygu anlatımıyla birleştirerek Rönesans\'ın en saygın ustası olmuştur.'),
  ('Josquin des Prez\'nin 1480\'lerde bestelediği ve dört sesin sırayla taklitli giriş yaptıktan sonra \'Ave vera virginitas\' kesitinde berrak akorlarda buluştuğu ünlü motet hangisidir?', 'Ave Maria... virgo serena', ['Spem in alium', 'Sicut cervus', 'O magnum mysterium'], '\'Ave Maria... virgo serena\', simetrik ses çiftleri, taklitli kontrpuan ve homofonik nefes alma noktalarıyla Yüksek Rönesans üslubunun manifestosu kabul edilir.'),
  ('15. ve 16. yüzyıllarda Dufay\'den Palestrina\'ya kadar kırktan fazla bestecinin Katolik Missa ayinine temel ezgi (cantus firmus) olarak kullandığı Fransız dünyevi asker şarkısı hangisidir?', 'L\'homme armé', ['Au clair de la lune', 'Malbrough s\'en va-t-en guerre', 'Frère Jacques'], '\'Silahlı adamdan korkulmalı\' sözleriyle başlayan \'L\'homme armé\', Rönesans boyunca bestecilerin çoksesli Missa ustalığını kanıtladıkları en popüler dünyevi ezgi olmuştur.'),
  ('1545–1563 yılları arasında toplanan Katolik Trento (Tridentinum) Konsili\'nin kilise müziğinden beklediği en temel reform neydi?', 'Kutsal Latince metnin karmaşık polifoni içinde boğulmayıp anlaşılır biçimde duyulması', ['Tüm kilise korolarına kadın sopranoların ve vurmalı çalgıların dahil edilmesi', 'Ayinlerin yerel halk dillerinde halk türküsü ezgileriyle topluca söylenmesi', 'Çoksesli müziğin bütünüyle yasaklanıp yalnızca org doğaçlamasına izin verilmesi'], 'Karşı-Reform hareketinin parçası olan Trento Konsili, dünyevi şarkı alıntılarına karşı çıkmış ve kutsal sözlerin berrak biçimde anlaşılmasını şart koşmuştur.'),
  ('Palestrina\'nın kontrpuan üslubunda ezgisel çizginin büyük bir aralıkla yukarı sıçradıktan sonra nasıl devam etmesi beklenir?', 'Ters yönde yanaşık adımlarla yumuşak biçimde aşağı dönerek denge kurması', ['Aynı yönde iki oktav daha sıçrayarak en tiz ses sınırını zorlaması', 'Kromatik yarım seslerle keskin uyumsuz akorlar üzerinde asılı kalması', 'Uzun bir timpani vuruşu eşliğinde tam suskuyla aniden kesilmesi'], 'Klasik vokal polifoninin altın standardı sayılan \'Palestrina üslubu\', sıçramaların hemen ardından ters yönde yanaşık hareketle dengelendiği pürüzsüz bir ezgi kemeri kurar.'),
  ('Jean Calvin öncülüğündeki Kalvinist Reform kiliselerinin müzik konusundaki tutumu, Lutherci kiliselerden hangi yönüyle keskin biçimde ayrılırdı?', 'Çalgıları ve çoksesliliği ibadetten çıkarıp yalnızca tek sesli mezmur okunmasına izin vermesiyle', ['İbadetlerde İtalyanca opera aryalarının orkestra eşliğinde söylenmesini teşvik etmesiyle', 'Kiliselere dev pedallı orglar ve bakır üflemeli toplulukları yerleştirmesiyle', 'Yalnızca Latince Gregoryen sekanslarının profesyonel korolarca okunmasını emretmesiyle'], 'Kalvinizm dünyevi süsten kaçınmak amacıyla kilisede çalgıları yasaklamış ve \'Cenevre Mezmurlar Kitabı\'ndaki uyaklı Davut mezmurlarının cemaatçe tek sesli okunmasını benimsemiştir.'),
  ('Yaşamı boyunca tek bir dünyevi şarkı veya madrigal yazmayıp tüm sanatını Katolik mistisizmine adayan, \'O magnum mysterium\' ve \'Officium Defunctorum\'un İspanyol bestecisi kimdir?', 'Tomás Luis de Victoria', ['Clément Janequin', 'Thomas Morley', 'Luca Marenzio'], 'Ávilalı rahip-besteci Tomás Luis de Victoria, Roma\'da Palestrina çevresinde bulunmuş, yoğun duygusal ve mistik anlatımlı yalnızca dini çoksesli eserler vermiştir.'),
  ('İtalyanca madrigal, Fransızca şanson, Almanca Lied ve Latince motet türlerinin tümünde usta işi iki binden fazla eser vererek Geç Rönesans\'ın en kozmopolit bestecisi sayılan sanatçı kimdir?', 'Orlando di Lasso', ['John Taverner', 'Jacob Arcadelt', 'Gilles Binchois'], 'Münih\'teki Bavyera sarayında uzun yıllar çalışan Flaman asıllı Orlando di Lasso (Orlande de Lassus), dönemin bütün ulusal dillerinde ve türlerinde başyapıtlar üretmiştir.'),
  ('Erken dönem İtalyan madrigalinin en sevilen örneklerinden olan ve kuğunun ölürken şarkı söylemesi metaforunu işleyen \'Il bianco e dolce cigno\' adlı dört sesli eserin bestecisi kimdir?', 'Jacques Arcadelt', ['Cipriano de Rore', 'Carlo Gesualdo', 'Adriano Banchieri'], 'Franko-Flaman kökenli Jacques Arcadelt\'in 1539\'da yayımlanan \'Il bianco e dolce cigno\' (Beyaz ve tatlı kuğu) madrigali, yüzyıl boyunca defalarca basılan bir klasik olmuştur.'),
  ('Geç Rönesans İtalyan madrigalinde kuralları zorlayan aşırı kromatik yürüyüşleri ve uzak ton sıçramalarıyla tanınan, \'Moro, lasso, al mio duolo\'nun bestecisi Venosa Prensi kimdir?', 'Carlo Gesualdo', ['Giovanni Gabrieli', 'Costanzo Festa', 'Orazio Vecchi'], 'Trajik özel yaşamıyla da bilinen Venosa Prensi Carlo Gesualdo, acı ve ölüm imgelerini yansıtmak için döneminin çok ötesinde sarsıcı kromatik armoniler kullanmıştır.'),
  ('16. yüzyıl Paris şanson okulunun en özgün ismi olup kuş cıvıltılarını (\'Le Chant des oiseaux\') ve Marignano Savaşı\'nın top-kılıç seslerini (\'La Guerre\') koro heceleriyle taklit eden besteci kimdir?', 'Clément Janequin', ['Josquin des Prez', 'Pierre de La Rue', 'Antoine Busnois'], 'Clément Janequin, betimleyici (programatik) şansonlarıyla tanınır; insan seslerine borazan, tüfek ve kuş ötüşlerini yansıtan onomatopeik heceler söyletmiştir.'),
  ('İngiliz Rönesans bestecisi Thomas Tallis\'in sekiz ayrı beş sesli koroyu birleştirerek toplam kırk bağımsız vokal parti için yazdığı anıtsal motet hangisidir?', 'Spem in alium', ['If ye love me', 'Sing joyfully', 'Ave verum corpus'], 'Kraliçe I. Elizabeth döneminde bestelenen kırk sesli \'Spem in alium\', ses kütlesinin mekân içinde dalga dalga dolaştığı eşsiz bir polifonik mimari harikasıdır.'),
  ('Anglikan İngiltere\'de Kraliçe I. Elizabeth\'in Kraliyet Şapeli\'nde görev alıp müzik basım tekeli edinmesine rağmen gizlice Katolik cemaat için üç Latince Missa besteleyen usta kimdir?', 'William Byrd', ['Henry Purcell', 'Orlando Gibbons', 'Thomas Weelkes'], 'Thomas Tallis\'in öğrencisi olan William Byrd, sadık bir Katolik olarak kalmış; hem Anglikan kilisesi için İngilizce \'anthem\'ler hem de gizli ev ayinleri için Latince Missalar yazmıştır.'),
  ('İngiltere\'de Reform sonrası Anglikan kilise ayinlerinde Latince motetin yerini alan, İngilizce kutsal metinler üzerine bestelenen koro eserlerine ne ad verilir?', 'Anthem', ['Frottola', 'Villancico', 'Lauda'], 'Anglikan litürjisinde tam koro için yazılanlara \'full anthem\', solo seslerle koronun org eşliğinde nöbetleştiği türe ise \'verse anthem\' adı verilmiştir.'),
  ('1588\'de Londra\'da yayımlanan \'Musica Transalpina\' derlemesinin İngiliz müzik yaşamındaki en önemli etkisi ne olmuştur?', 'İtalyan madrigal örneklerini İngilizce sözlerle tanıtarak İngiliz madrigal okulunu başlatması', ['Alman org füglerini İngiliz katedrallerinde zorunlu tören müziği haline getirmesi', 'Fransız saray balesini Londra halk tiyatrolarına taşıyarak konuşmalı dramı bitirmesi', 'İspanyol gitar tablaturunu öğreterek lavta kullanımını tamamen ortadan kaldırması'], 'Nicholas Yonge\'un yayımladığı \'Musica Transalpina\' (Alplerin Ötesinden Müzik), Marenzio ve Palestrina madrigallerini İngilizceye uyarlayarak büyük bir madrigal tutkusu doğurmuştur.'),
  ('Thomas Morley\'nin \'Now is the month of maying\' adlı eserinde olduğu gibi, kıta sonlarında \'fa-la-la\' heceli neşeli nakaratlar içeren dans karakterli İngiliz madrigal alt türü hangisidir?', 'Ballett', ['Pavane', 'In Nomine', 'Dump'], 'İtalyan \'balletto\'sundan (Gastoldi) esinlenen İngiliz \'ballett\' türü, homofonik kıta dokusu ve \'fa-la-la\' nakaratlarıyla kolay akılda kalan şenlikli bir vokal formdur.'),
  ('Rönesans saray şölenlerinde genellikle art arda çalınan dans çiftlerinden hangisi \'ağırbaşlı ikili ölçüde yürüyüş dansı – canlı üçlü ölçüde sıçramalı dans\' karşıtlığına dayanır?', 'Pavane ve Galliard', ['Minuet ve Trio', 'Polonez ve Mazurka', 'Vals ve Galop'], '16. yüzyılın en yaygın dans çiftinde ağır ve törensel ikili zamanlı \'pavane\'ı, aynı ezgisel malzemeyi üçlü zamanda enerjik sıçramalarla işleyen \'galliard\' izlerdi.'),
  ('16. yüzyıl İspanya\'sında lavtanın yerini alan, gitar biçimli düz sırtlı gövdeye sahip fakat lavta gibi çiftli altı tel düzeniyle akortlanan soylu çalgı hangisidir?', 'Vihuela', ['Mandolin', 'Balalayka', 'Bandora'], 'Luis de Milán ve Luis de Narváez gibi İspanyol Rönesans ustaları, Arap kökenli çağrışımlar taşıyan armudi lavta yerine düz gövdeli zarif \'vihuela\' için zengin bir repertuvar yaratmıştır.'),
  ('Rönesans çalgı yapımında blokflüt, krummhorn veya viola da gamba gibi aynı aileden çalgıların sopranodan basa farklı boylarda bir takım halinde bir arada çalınmasına ne ad verilirdi?', 'Tam konsort (Whole consort)', ['Sürekli bas grubu', 'Kırık konsort (Broken consort)', 'Senfonik üflemeli bandosu'], 'Aynı çalgı ailesinin farklı ses boylarından oluşan homojen topluluğa \'tam konsort\', farklı ailelerden (örneğin flüt, keman, lavta, sitern) karma topluluğa ise \'kırık konsort\' denirdi.'),
  ('Kıvrık bir baston (J harfi) biçimindeki ahşap gövdesinin içinde kapsüllü çift kamış bulunan ve vızıltılı burunsu bir tını üreten Rönesans üflemeli çalgısı hangisidir?', 'Krummhorn', ['Kornetto', 'Sackbut', 'Traverso'], 'Almanca \'eğri boynuz\' anlamına gelen krummhorn\'da çalgıcının dudakları kamışa doğrudan değmez; hava rüzgâr kapsülünden geçerek sabit gürlükte karakteristik bir vızıltı üretir.'),
  ('Modern trombonun Rönesans ve erken Barok dönemdeki öncüsü olan, dar çanlı ve daha yumuşak tınılı sürgülü bakır üflemeli çalgının İngilizce tarihsel adı nedir?', 'Sackbut', ['Ophicleide', 'Bombarde', 'Clarin'], 'Fransızca \'çek-it\' (sacqueboute) kökünden gelen sackbut, teleskopik sürgüsü sayesinde Rönesans\'ta tam kromatik dizi çalabilen yegâne bakır üflemeli olmuş ve kilise korolarını desteklemiştir.'),
  ('Kraliçe I. Elizabeth dönemi İngiliz klavyeli çalgı müziğinin (Byrd, Bull, Farnaby, Gibbons) yaklaşık üç yüz parçasını günümüze taşıyan en büyük el yazması antoloji hangisidir?', 'Fitzwilliam Virginal Kitabı', ['Anna Magdalena Bach Defteri', 'Mulliner Org Kitabı', 'Eton Koro Kitabı'], 'Cambridge\'deki Fitzwilliam Müzesi\'nde korunan bu dev el yazması, İngiliz virginalist okulunun danslar, fanteziler ve halk ezgisi çeşitlemelerini içeren eşsiz hazinesidir.'),
  ('Rönesans çoksesli vokal müziğinde başlangıçta vokal motetin çalgısal karşılığı olarak doğan, bir temayı birbiri ardına taklitli biçimde işleyen ve Barok fügün atası sayılan çalgı formu hangisidir?', 'Ricercar', ['Toccata', 'Tarantella', 'Rigaudon'], 'İtalyanca \'aramak/araştırmak\' anlamına gelen ricercar, org veya çalgı topluluğu için ağırbaşlı imitatif kontrpuanla yazılan ve füg formuna evrilen entelektüel bir türdür.'),
  ('Fransızca şansonların çalgılara uyarlanmasından gelişen, \'uzun–kısa–kısa\' (daktilik) açılış ritmi ve canlı karşıt kesitleriyle Barok sonatın öncüsü olan Rönesans çalgı formu hangisidir?', 'Canzona', ['Sarabande', 'Ground bass', 'Chaconne'], 'Canzona (canzona da sonar), şanson kökenli enerjik ritmi ve kesitli yapısıyla 16. yüzyıl sonu Venedik çalgı müziğinden 17. yüzyıl kilise sonatına geçiş köprüsü kurmuştur.'),
  ('İmparator V. Karl\'ın en sevdiği şarkı olan ve daha sonra Cristóbal de Morales tarafından bir Missa\'ya temel alınan dört sesli hüzünlü şanson \'Mille regretz\' (Bin Pişmanlık/Hüzün) kime atfedilir?', 'Josquin des Prez', ['Clément Janequin', 'Adrian Willaert', 'Thomas Tallis'], 'Yalın ve derin kederli dokusuyla \'İmparatorun Şarkısı\' (Canción del Emperador) olarak da anılan \'Mille regretz\', Josquin des Prez ile özdeşleşmiş en ünlü şansondur.'),
  ('16. yüzyıl İspanya ve Portekiz\'inde hem sarayda dünyevi konularla hem de Noel gibi dini bayramlarda yerel dilde nakaratlı kıtalarla söylenen popüler çoksesli şarkı türü hangisidir?', 'Villancico', ['Frottola', 'Conductus', 'Chanson de geste'], '\'Köylü şarkısı\' kökünden gelen İber Yarımadası\'na özgü villancico, nakarat (estribillo) ve kıta (copla) yapısıyla Juan del Encina gibi ustaların elinde çok sevilmiştir.'),
  ('İtalya\'da özellikle Filip Neri\'nin Roma\'daki dua toplantılarında halkın kolayca eşlik edebilmesi için İtalyanca dinsel şiirler üzerine söylenen yalın, homofonik övgü şarkılarına ne ad verilirdi?', 'Lauda', ['Caccia', 'Ballade', 'İzoritmik motet'], 'Orta Çağ\'dan Rönesans\'a uzanan \'lauda\', Latince litürji dışında yerel dilde söylenen sıcak, akorsal dinsel halk ilahisidir ve Filip Neri\'nin toplantılarında oratoryoya zemin hazırlamıştır.'),
  ('Rönesans çoksesli eserlerinin sonunda minör karakterli bir modda ilerleyen parçanın en son akorunda üçlü sesin tizleştirilerek parlak bir majör üçlü akorla bitirilmesine ne ad verilir?', 'Pikardi üçlüsü', ['Frigya yarım kadansı', 'Altominant kalışı', 'Landini kadansı'], 'Minör üçlüyü karar anında yeterince dingin bulmayan Rönesans ve Barok estetiğinde, son akorun üçlüsünü diyezleştirerek majör tınlatma uygulamasına \'Pikardi üçlüsü\' denir.'),
  ('Rönesans koro uygulamalarında tüm şarkıcıların önlerindeki tek bir dev el yazmasının çevresinde ayakta toplanarak aynı iki açık sayfadan kendi partilerini okumalarına olanak tanıyan kitap biçimi hangisidir?', 'Koro kitabı (Choirbook) düzeni', ['Cep partisyonu formatı', 'Bireysel rulo şeritler', 'Dört yönlü masa kitabı'], 'Choirbook formatında partiler üst üste partisyon gibi değil; sol sayfanın üst ve altına iki parti, sağ sayfanın üst ve altına diğer iki parti gelecek şekilde ayrı bölgelere yazılırdı.'),
  ('16. yüzyıl müzik baskılarında her ses partisinin (Cantus, Altus, Tenor, Bassus) ayrı ayrı ince kitapçıklar halinde basıldığı yayın biçimine ne ad verilir?', 'Parti kitapları', ['Tam orkestra şef partisyonu', 'Sürekli bas klavye özeti', 'Kare notalı antifoner'], 'Rönesans\'ta müzisyenler diğer partileri görmeden yalnızca kendi seslerini içeren \'partbook\' kitapçıklarından okuyor, kulaklarıyla diğer sesleri dinleyerek uyum sağlıyordu.'),
  ('Orlando Gibbons\'ın 1612 tarihli \'The Silver Swan\' (Gümüş Kuğu) adlı beş sesli eseri, İngiliz Rönesans müziğinin hangi türdeki başyapıtlarından biridir?', 'Madrigal / Konsort şarkısı', ['Latince Requiem ayini', 'İtalyanca komik opera', 'Trompetli saray uvertürü'], 'Ölüm döşeğindeki kuğunun bilgeliğin azalmasından yakınmasını anlatan \'The Silver Swan\', Gibbons\'ın en sevilen beş sesli İngiliz madrigal/konsort şarkısıdır.'),
  ('16. yüzyıl sonunda saray balolarında erkek dansçının partnerini belinden kavrayıp havaya sıçratarak döndürdüğü için muhafazakâr çevrelerce cüretkâr bulunan ancak Kraliçe I. Elizabeth\'in çok sevdiği üçlü zamanlı dans hangisidir?', 'Volta', ['Basse danse', 'Pavane', 'Allemande'], 'Provence kökenli \'La Volta\', eşlerin birbirine yakın teması ve kadının havaya kaldırılıp döndürülmesiyle Rönesans\'ın en hareketli ve tartışmalı saray dansı olmuştur.'),
  ('Alman besteci Michael Praetorius\'un 1619\'da yayımladığı \'Syntagma Musicum\' adlı üç ciltlik ansiklopedik eser, müzik tarihçileri için neden paha biçilmez bir kaynaktır?', 'Geç Rönesans ve erken Barok çalgılarının ölçekli gravür çizimlerini ve akort bilgilerini içermesiyle', ['Beethoven\'a kadar uzanacak senfoni formunun kurallarını önceden belirlemesiyle', 'Antik Mısır tapınak müziğinin hiyeroglif notalarını çözerek yayımlamasıyla', 'Avrupa\'daki tüm katedrallerin mimari akustik yankı sürelerini saniye cinsinden ölçmesiyle'], 'Syntagma Musicum\'un \'Theatrum Instrumentorum\' bölümü, dönemin tüm üflemeli, telli ve vurmalı çalgılarını gerçek boyut ölçeğiyle gösteren eşsiz ahşap baskı levhalara sahiptir.'),
  ('Rönesans\'ta bas ses alanını desteklemek üzere geliştirilen, S harfi veya yılan biçiminde kıvrımlı ahşap gövdeye sahip ve fincan ağızlıkla üflenen pes çalgı hangisidir?', 'Serpent', ['Rebec', 'Spinet', 'Bandora'], '16. yüzyıl sonunda Fransa\'da kilise düz ezgilerini bas bölgede güçlendirmek için icat edilen \'serpent\', yılan biçimli kıvrımları sayesinde parmakların ses deliklerine yetişebildiği kornetto ailesinin bas üyesidir.'),
  ('15. yüzyıl sonunda Josquin\'in kuşağıyla birlikte vokal çokseslilikte \'seslerin eşitliği\' ilkesinin yerleşmesi, bas partisinin rolünü Orta Çağ\'a kıyasla nasıl değiştirmiştir?', 'Bas partisi diğer seslerle taklitli kontrpuan paylaşırken aynı zamanda armonik temeli kuran en pes sese dönüşmüştür', ['Bas partisi tamamen sözsüz bırakılarak yalnızca vurmalı çalgılara devredilmiştir', 'Bas partisi en tiz ezgi çizgisinin tam beşli üstüne taşınarak tizleştirilmiştir', 'Bas partisi eserin başından sonuna dek tek bir dem notasını aralıksız tutmaya başlamıştır'], 'Rönesans\'ta dört sesli standart koro dokusu (soprano/cantus, alto, tenor, bassus) oturmuş; tenorun altındaki \'bassus\' hem taklitlere katılmış hem de akor köklerini taşıyan armonik direk olmuştur.'),
  ('Fransız rahip Thoinot Arbeau\'nun 1589\'da diyalog biçiminde yayımladığı \'Orchésographie\' adlı kitap, Rönesans kültürü hakkında hangi temel bilgiyi günümüze ulaştırmıştır?', 'Pavane, galliard, branle gibi Rönesans danslarının adım şemalarını ve davul-ezgi kalıplarını', ['Katedral orglarının kurşun ve kalay boru döküm formüllerini', 'Sistina Şapeli\'ndeki gizli vokal süsleme ve kastrato eğitimi yöntemlerini', 'Venedik tersanesinde yapılan lavta ve keman verniklerinin kimyasal reçetelerini'], 'Jehan Tabourot\'nun anagram mahlasıyla (Thoinot Arbeau) yazdığı \'Orchésographie\', 16. yüzyıl Avrupa sosyal ve saray danslarının adımlarını müzik notalarıyla yan yana gösteren en temel kaynaktır.'),
  ('16. yüzyıl sonunda Luca Marenzio\'nun yazdığı madrigaller, çağdaşları tarafından hangi estetik özellikle özdeşleştirilmiştir?', 'Pastoral doğa imgelerini zarif ve duyusal kelime boyamalarıyla kristal berraklığında işlemesiyle', ['Savaş toplarını ve davul gürültülerini on iki bakır çalgıyla taklit etmesiyle', 'Yalnızca tek sesli Gregoryen ilahilerini org eşliğinde sadeleştirmesiyle', 'Alman esnaf loncalarının sıkı kurallı Bar formunu İtalyancaya uyarlamasıyla'], '\'En tatlı kuğu\' lakabıyla anılan Luca Marenzio, \'Solo e pensoso\' gibi eserlerinde şiirsel imgeleri zarafet ve armonik incelikle resmeden geç Rönesans madrigal ustasıdır.'),
  ('16. yüzyıl Venedik\'inde San Marco Bazilikası\'nın \'maestro di cappella\'lık görevinin ülke çapında en prestijli müzik makamı sayılmasının nedeni neydi?', 'Doğrudan Venedik Dükü\'ne bağlı devlet töreni merkezi olup en seçkin şarkıcı ve çalgıcıları yüksek maaşla istihdam etmesi', ['Avrupa\'da yalnızca kadın bestecilerin yönetmesine izin verilen tek katedral olması', 'Papa\'nın yazlık sarayı içinde yer alıp kardinaller meclisini denetlemesi', 'Bütün Avrupa konservatuvarlarına diploma verme yetkisini elinde bulundurması'], 'San Marco Bazilikası piskoposluk katedrali değil Venedik Cumhuriyeti Dükü\'nün (Doge) resmi devlet şapeliydi; Cumhuriyetin zenginliğini simgelemek için en parlak müzisyenleri toplamıştır.'),
  ('İngiltere\'de VIII. Henry, VI. Edward, Kanlı Mary ve I. Elizabeth gibi dört farklı hükümdarın sık sık değişen Katolik-Protestan mezhep politikalarına uyum sağlayarak hayatta ve görevde kalmayı başaran usta besteci kimdir?', 'Thomas Tallis', ['Henry Lawes', 'Matthew Locke', 'Pelham Humfrey'], 'Thomas Tallis, Tudor hanedanının çalkantılı din değişimlerinde hem görkemli Latince Katolik polifonisi hem de yalın İngilizce Protestan koralleri/anthemleri yazarak ustalığını sürdürmüştür.'),
  ('Rönesans müziğinde kullanılan ritmik nabız birimi \'tactus\', modern orkestra şefliğinden farklı olarak nasıl uygulanırdı?', 'Elin sabit ve düzenli bir hızla aşağı-yukarı hareketiyle ani tempo dalgalanmaları olmaksızın nabzı koruyarak', ['Fildişi bir bagetle her ölçüde hızı iki katına çıkarıp yavaşlatan rubato dalgalarıyla', 'Ağır demir bir asayı döşeme tahtalarına hızla vurarak ritmi değiştirmekle', 'Metronom sarkacının elektrikli ziliyle her on altıncı notayı saydırmakla'], 'Rönesans polifonisinde istikrarlı insan kalp atışına yakın (dakikada 60–70 vuruş) düzenli bir aşağı-yukarı el hareketi olan \'tactus\' tüm sesleri bir arada tutardı.'),
  ('Claudin de Sermisy\'nin \'Tant que vivray\' adlı eserinde görülen ve İtalyan veya Flaman şansonundan ayrılan \'Paris şansonu\'nun temel niteliği aşağıdakilerden hangisidir?', 'Üst seste akılda kalıcı zarif bir ezgi, eş ritimli hafif doku ve hecesel (silabik) Fransızca söyleyiş', ['Sekiz sesli yoğun kanonik kontrpuan ve anlaşılması güç çok dilli metin kurgusu', 'Ağır cenaze yürüyüşü temposu ve sürekli kromatik yarım ses inlemeleri', 'Sürekli bas eşliğinde doğaçlama koloratur aryalar içeren dramatik yapı'], 'I. François dönemi Paris şansonu (Sermisy, Janequin), Flaman okulunun ağır kontrpuanı yerine hafif, ritmik, homofoni ağırlıklı ve zarif bir saray eğlence üslubu geliştirmiştir.'),
  ('Orta Çağ motetinden Rönesans motetine geçişte (15. yüzyıl ortasından 16. yüzyıla) yaşanan en belirgin dönüşüm aşağıdakilerden hangisidir?', 'Çok dilli dünyevi-dini metin karmaşasının bırakılıp tek bir kutsal Latince metin üzerine dingin imitatif polifoni yazılması', ['Latincenin tamamen terk edilerek yalnızca Oksitan dilinde şövalye aşklarının işlenmesi', 'İnsan seslerinin kaldırılıp motetin yalnızca davul ve trompet fanfarına dönüştürülmesi', 'Üç ve dört sesli dokunun bırakılıp yeniden tek sesli Gregoryen ezgisine dönülmesi'], '13. yüzyılın çok metinli ve izoritmik moteti, Rönesans\'ta tek bir kutsal Latince metni her cümlesinde yeni bir taklit noktasıyla işleyen homojen çoksesli dini türe dönüşmüştür.'),
  ('1500\'lü yıllarda halk arasında yayılan çılgın \'La Folia\' (Delilik) dans şemasının, sonraki üç yüzyıl boyunca Corelli\'den Vivaldi ve Rachmaninoff\'a dek yüzlerce esere konu olan özelliği nedir?', 'Karakteristik noktalı sarabande ritmiyle ilerleyen etkileyici minör akor-bas yürüyüşü', ['On bir zamanlı aksak ölçüsü ve vurmalı çalgıların doğaçlama soloları', 'Yalnızca flageolet (doğuşkan) seslerle çalınabilen tiz keman ezgisi', 'Her çeşitlemede yarım ton yukarı modülasyon yapan on iki tonluk yapısı'], 'İber Yarımadası kökenli \'Folia\' şeması (i–V–i–VII–III–VII–i–V), Rönesans ve Barok müziğinin en ünlü ostinato armonik çeşitleme temalarından biri olmuştur.'),
  ('Rönesans hümanizminin Antik Yunan metinlerini yeniden keşfetmesi, 16. yüzyıl bestecilerinin müziğe bakışını hangi yönde değiştirmiştir?', 'Müziği soyut sayısal kozmos bilimi olmaktan çıkarıp sözün retorik ve duygusal ikna gücünü artıran bir ifadeye dönüştürmüştür', ['Çoksesli müziği matematiksel kusur sayarak bütün çalgıların yakılmasına yol açmıştır', 'Bestecileri insan sesinden uzaklaştırıp yalnızca astronomik gezegen tabloları çizmeye yöneltmiştir', 'Avrupa dillerinde şarkı yazmayı yasaklayıp yalnızca Eski Yunanca destanlar okutmuştur'], 'Orta Çağ müziği Quadrivium içinde matematiksel oran olarak görürken, Rönesans hümanizmi müziği şiir ve retorikle (Trivium) birleştirerek dinleyicide duygu (affetto) uyandırma sanatına çevirmiştir.'),
  ('Klavsen icracısının parmak vuruş hızını değiştirmesine karşın tek bir tel dizisinde ses gürlüğünün (piano/forte) neredeyse hiç değişmemesinin mekanik nedeni nedir?', 'Mızrabın teli her vuruşta sabit esneklik mesafesiyle çekip bırakması', ['Tellerin kurşun alaşımlı ağır susturucularla sürekli örtülü olması', 'Ses tahtasının meşe ağacı yerine kalın mermer plakadan üretilmesi', 'Tuşların altında yaylı hidrolik basınç dengeleyicilerin bulunması'], 'Çekiçli piyanodan farklı olarak klavsende mızrabın teli büküp kurtulma genliği parmak gücünden büyük ölçüde bağımsızdır; bu yüzden teraslı tını değişimi için çift klavye veya kuplaj kullanılır.'),
  ('Büyük konser klavsenlerinde üst üste iki klavye (manuel) bulunmasının icracıya sağladığı en önemli olanak nedir?', 'Farklı tını ve gürlükteki tel grupları arasında anında karşıtlık veya birleştirme yapabilmek', ['İki farklı akort sistemindeki eseri telleri sökmeden aynı anda çalabilmek', 'Alt klavyeyle körüğü pompalarken üst klavyeyle boru seslerini yönetebilmek', 'Pedal kullanmadan dört oktav daha kalın kontrbas seslerine inebilmek'], 'Çift klavyeli klavsenlerde bir klavye parlak ve gür (8\' + 4\' kuplajlı), diğer klavye daha yumuşak tek sıra tel çalarak Barok \'teraslı dinamik\' karşıtlığını kolayca üretir.'),
  ('Klavyeli çalgılar arasında yalnızca klavikorda özgü olan ve basılı tutulan tuş üzerindeki parmak basıncını dalgalandırarak sese hafif bir vibrato kazandırma tekniğine Almancada ne ad verilir?', 'Bebung', ['Scordatura', 'Martelé', 'Flatterzunge'], 'Klavikordda metal dil (tangent) tel ile doğrudan temasta kaldığı için parmak ağırlığının ritmik değişimi tel gerginliğini esneterek \'Bebung\' adı verilen duygulu vibratoyu doğurur.'),
  ('Barok kilise orgunda icracının konsol yanındaki kolları (register/stop) çekip itmesi mekanik olarak hangi işlevi yerine getirir?', 'Belirli tını ve boydaki boru sıralarına rüzgâr sandığından hava girişini açıp kapatmayı', ['Orgun tüm borularını yarım ton tizleştirip pesleştiren yayları germeyi', 'Körük başındaki yardımcılara zil çalarak tempo değişikliğini bildirmeyi', 'Kilise kubbesindeki akustik kapakları halatlarla açıp daraltmayı'], 'Orgda her durak (register/stop) flüt, principal veya kamışlı (reed) gibi ayrı bir boru sırasını kontrol eder; kol çekildiğinde sürgü açılarak o boru dizisinin ses vermesi sağlanır.'),
  ('Barok kilise orglarında yalnız Kuzey ve Orta Almanya geleneğinde çok gelişmiş olup Fransız ve İtalyan orglarında daha sınırlı kalan, bağımsız bas kontrpuan partilerini ayaklarla çalmaya yarayan bölüm hangisidir?', 'Tam kapsamlı pedal klavyesi', ['Su basıncıyla çalışan hidrolik kazan', 'Kuş tüyü mızraplı çembalo eki', 'Otomatik delikli karton silindir'], 'Alman Barok orglarındaki geniş ve bağımsız boru kulelerine sahip pedal klavyesi, Bach\'ın ellerde iki ayrı ses çalarken ayaklarıyla karmaşık bas füg temalarını seslendirmesine olanak tanımıştır.'),
  ('1600 yılı dolaylarında İtalya\'da sürekli bas (basso continuo) eşliğinde güçlü pes sesler elde etmek amacıyla lavtanın sapına ikinci bir uzun burgu kutusu ve perdesiz bas telleri eklenerek geliştirilen dev çalgı hangisidir?', 'Theorbo', ['Mandora', 'Vihuela', 'Rebec'], 'Erken opera ve monodi eşliği için geliştirilen theorbo (tiorba / chitarrone), yaklaşık iki metreye varan boyu ve klavye dışından uzanan diyapazon bas telleriyle Barok toplulukların vazgeçilmezi olmuştur.'),
  ('Rönesans ve Barok yaylı çalgı ailesi \'viola da gamba\' ile modern keman/viyolonsel ailesi karşılaştırıldığında aşağıdaki özelliklerden hangisi viola da gamba\'ya aittir?', 'Sapında bağırsak perdeler bulunması, altı-yedi telli olması ve yayın avuç içi yukarı bakacak biçimde alttan tutulması', ['Dört adet perdesiz çelik tele sahip olması ve çenenin sol altına sıkıştırılarak ayakta çalınması', 'Yere saplanan uzun metal pik (endpin) üzerinde yüksek tel tansiyonuyla gür ses üretmesi', 'Tam beşli aralıklarla akortlanıp yalnızca orkestra yürüyüşlerinde bakırları bastırması'], 'Bacaklar arasında tutulan (\'da gamba\') bu soylu aile; eğik omuzları, düz sırtı, C biçimli ses delikleri, sapındaki perdeleri, dörtlü-üçlü akordu ve alttan (underhand) yay tutuşuyla çellodan tamamen farklıdır.'),
  ('Yayla çalınan asıl bağırsak tellerinin hemen altından köprü içinden geçerek tuşenin altından uzanan ve yay değmeden kendiliğinden tınlayan ince metal \'sempatik (eşlikçi) tellere\' sahip Barok çalgı hangisidir?', 'Viola d\'amore', ['Viola pomposa', 'Tromba marina', 'Pochette'], 'Perdesiz omuzda tutulan ve salyangozunda çoğu kez gözleri bağlı Eros başı bulunan \'viola d\'amore\', sempatik rezonans telleri sayesinde gümüşsü ve buğulu bir tını üretir; Vivaldi bu çalgı için konçertolar yazmıştır.'),
  ('Barok dönemin keman yapısı, 19. yüzyılda modernize edilmiş günümüz kemanından hangi yönüyle ayrılır?', 'Daha kısa-kalın sap açısına, bağırsak tellere sahip olması ve çenelik/omuzluk olmadan çalınmasıyla', ['Altı adet çelik tele ve sap boyunca çakılmış pirinç perdelere sahip olmasıyla', 'Ses deliklerinin yuvarlak rozet şeklinde olup ses direğinin bulunmamasıyla', 'Gövdesinin çam ve akçaağaç yerine ince bakır levhalardan lehimlenmesiyle'], 'Barok kemanda tel gerginliği daha düşüktür, bağırsak (kiriş) teller kullanılır, bas balkonu daha incedir ve sap açısı daha düz olduğundan daha sıcak, şeffaf ve çabuk konuşan bir ses verir.'),
  ('17. ve 18. yüzyıl dans öğretmenlerinin ceket ceplerinde taşıyarak öğrencilere adım öğretirken hem ezgi hem ritim çaldıkları çok dar ve ince gövdeli minyatür kemana ne ad verilirdi?', 'Pochette', ['Rebec', 'Lirone', 'Baryton'], 'Fransızca \'cep\' (poche) kelimesinden gelen \'pochette\' (İngilizce kit), saray dans ustalarının ders sırasında kolayca cebinden çıkarıp çaldığı kayık veya dar keman biçimli çalgıdır.'),
  ('Barok partisyonlarda sıkça karşılaşılan İtalyanca \'flauto\' (veya \'flauto dolce\') ibaresi, aksi belirtilmedikçe hangi üflemeli çalgıyı kasteder?', 'Dikey üflenen gagalı blokflütü', ['Gümüş gövdeli modern Boehm flütünü', 'Kamışlı çoban kavalını', 'Sürgülü orkestra pikolosunu'], 'Barok dönemde yalın \'flauto\' sözcüğü her zaman blokflütü (recorder) ifade eder; yandan üflenen flüt kastedildiğinde özellikle \'flauto traverso\' veya \'traversa\' yazılırdı.'),
  ('Barok yan flütün (flauto traverso) 17. yüzyıl sonu Fransız ustaları (Hotteterre ailesi) tarafından yeniden tasarlanan yapısı nasıldı?', 'Şimşir veya fildişinden üç-dört parçalı konik ahşap gövde, altı açık parmak deliği ve yalnızca tek bir metal perde tuşu', ['Silindirik nikel-gümüş boru üzerinde on altı adet halkalı Boehm mekanizması tuşu', 'Çift kamışlı ağızlıkla dikey tutulan sekizgen deri kaplı gövde', 'Pirinçten kıvrımlı gövde üzerinde üç adet pistonlu valf mekanizması'], 'Barok traverso (tek tuşlu Re-diyez perdesiyle), ahşap konik iç çapı sayesinde kadifemsi bir tınıya ve tonlara göre değişen zengin çatallı parmak (forked fingering) renklerine sahipti.'),
  ('J. S. Bach\'ın kantat ve pasyonlarında pastoral veya içli sahneler için sıklıkla kullandığı, normal obuadan küçük üçlü daha pes (La akortlu) ve armut biçimli hazne kalağa (liebesfuss) sahip çalgı hangisidir?', 'Oboe d\'amore', ['Oboe sopranino', 'Şalümo', 'Heckelphone'], 'Armudi kalağı sayesinde örtük, sıcak ve dokunaklı bir tını veren \'oboe d\'amore\' (aşk obuası), 1720\'lerden itibaren özellikle Bach ve Telemann\'ın eserlerinde başrol oynamıştır.'),
  ('Barok trompet virtüözlerinin en tiz bölgede büyük dudak kontrolüyle seslendirdiği göz kamaştırıcı ve süslü trompet üslubuna (örneğin 2. Brandenburg Konçertosu\'nda) hangi ad verilir?', 'Clarino tekniği', ['Pizzicato stili', 'Sordino fısıltısı', 'Chalumeau bölgesi'], 'Barok trompet loncalarında alt doğuşkanları çalanlara \'principale\', en tiz ve parlak ezgisel bölgeyi dudak hüneriyle çalan seçkin ustalara ise \'clarino\' oyuncusu denirdi.'),
  ('17. yüzyılda Kutsal Roma İmparatorluğu\'nda doğal trompet ve timpani çalma hakkının sıkı lonca imtiyazlarıyla korunmasının toplumsal nedeni neydi?', 'Bu iki çalgının hükümdarlık, şövalyelik ve savaş egemenliğinin resmi saray simgesi kabul edilmesi', ['Kilisenin bakır madenini kutsal sayarak halkın dokunmasını yasaklaması', 'Trompet sesinin bulaşıcı hastalıkları iyileştirdiğine dair tıbbi inanç bulunması', 'Yalnızca üniversitede matematik doktorası yapanların bu çalgıları üfleyebilmesi'], 'İmparatorluk Trompetçi ve Timpanici Loncası (Kameradschaft), bu çalgıların sokak eğlencelerinde sıradanlaştırılmasını yasaklamış; yalnız prens sarayları, süvari alayları ve büyük kilise bayramlarına özgü kılmıştır.'),
  ('Barok partisyonlarda yaylı çalgılar grubunun en pes partisini belirten \'violone\' terimi genel olarak hangi çalgı işlevini tanımlar?', 'Sekizli veya on altılı pes bölgede bas çizgisini katlayan büyük bas gamba / erken kontrbas ailesini', ['Kemanın bir oktav tizinden çalan çok küçük cep kemanını', 'Yalnızca arpejli akorlar basan on iki telli İspanyol gitarını', 'Omuz askısıyla yürürken çalınan tek kamışlı askeri boruyu'], 'İtalyanca \'büyük viol\' anlamına gelen violone, 17. ve 18. yüzyıllarda bölgeye göre 8 ayak veya 16 ayak (bir oktav alttan katlayan) bas yaylı çalgıyı ifade etmiştir.'),
  ('Kuzey Avrupa (Flaman ve Hollanda) şehirlerinin belediye ve katedral kulelerine yerleştirilen, dev bir ahşap yumruk klavyesi ve ayak pedallarıyla ezgili biçimde çalınan onlarca akortlu bronz çan düzenine ne ad verilir?', 'Karilyon', ['Glockenspiel', 'Çelesta', 'Sistrum'], 'Rönesans sonu ve Barok dönemde Alçak Ülkeler\'de Hemony kardeşlerin akort sanatıyla olgunlaşan \'karilyon\', kule çanlarını tam kromatik bir klavyeli çalgıya dönüştürmüştür.'),
  ('Barok yaylı çalgı icrasında tüm telleri standart akort düzeninden farklı perdelere çekerek özel akor tınıları ve kolay çift sesler elde etme tekniğine (örneğin Biber\'in Tespih Sonatları\'nda) ne ad verilir?', 'Scordatura', ['Col legno', 'Sul ponticello', 'Portamento'], 'İtalyanca \'yanlış/farklı akortlama\' anlamına gelen scordatura, Heinrich Ignaz Franz Biber\'in on beş gizemli \'Rosenkranz (Tespih) Sonatı\'nda her sonat için farklı bir tel düzeni kurmasıyla zirveye çıkmıştır.'),
  ('Barok çalgı yapımında İngiliz ve İtalyan küçük ev klavsenlerinden \'spinet\'in kanat veya üçgenimsi asimetrik formunun temel işlevi nedir?', 'Tellerin klavyeye yaklaşık otuz-kırk beş derecelik eğik açıyla dizilerek dar odalarda yer tasarrufu sağlaması', ['Çalgının gemi güvertesinde rüzgârı keserek yelken görevi görmesi', 'İki icracının sırt sırta oturup aynı telleri çekebilmesine imkân vermesi', 'Sesin yalnızca tavana doğru dikey yansımasını önleyip yere gömmesi'], 'Büyük klavsende teller dik, virginalde yatay/paralel uzanırken, Bentside spinet\'te teller eğik açıyla yerleştirilerek küçük hacimde tatmin edici bas tel uzunluğu elde edilmiştir.'),
  ('Metal sargılı bas tellerin 1660\'larda Bologna\'da icat edilmesi, yaylı çalgılar ailesindeki hangi çalgının hantal \'bas keman\' boyutundan küçülerek çevik bir solo çalgıya dönüşmesini sağlamıştır?', 'Viyolonselin', ['Rebec\'in', 'Pochette\'in', 'Tromba marina\'nın'], 'Saf bağırsak bas teller uzun gövde gerektirirken, gümüş sargılı Do ve Sol telleri sayesinde daha küçük ve çevik \'violoncello\' doğmuş ve Domenico Gabrielli gibi Bologna ustaları ilk solo çello eserlerini yazmıştır.'),
  ('Barok blokflüt ailesinde solo sonat ve konçertolarda (Handel, Telemann, Vivaldi) en çok tercih edilen standart solo çalgı, Do akortlu soprano blokflüt değil hangi boydaki blokflüttür?', 'Fa akortlu alto (treble) blokflüt', ['İki metre boyundaki büyük kontrbas blokflüt', 'Yalnızca üç delikli tek el çoban düdüğü', 'Çift borulu duble akor flütü'], 'Günümüz okul eğitiminde soprano blokflüt yaygın olsa da Barok dönemin asıl ciddi solo ve oda müziği blokflütü dolgun ve sıcak tınılı Fa-alto (treble) blokflüttür; ayrıca Vivaldi tiz \'flautino\' (sopranino) için de parlak konçertolar yazmıştır.'),
  ('Orta Çağ\'dan Rönesans\'a taşınan ve tek kişinin sol eliyle üç delikli ince bir düdük çalarken sağ eliyle koluna asılı küçük bir davula vurduğu halk dansı ikilisi hangisidir?', 'Boru ve davul', ['Şalümo ve timpani', 'Kornetto ve karilyon', 'Panflüt ve santur'], 'Üst doğuşkanlarıyla tek elle tam dizi çalabilen üç delikli \'pipe\' ve küçük \'tabor\' davulu, tek müzisyenin tek başına eksiksiz bir dans orkestrası olmasını sağlamıştır.'),
  ('17. yüzyılda Kuzey İtalya ve Güney Almanya kiliselerinde insan sesini en etkileyici biçimde taklit ettiği düşünülen kornetto virtüözleri, genellikle hangi bakır üflemeli çalgı grubuyla standart bir tören topluluğu oluştururdu?', 'Üç veya dört adet sackbut (erken trombon) ile', ['Altı adet valfli tuba ve suzafon ile', 'Çift sıra pikolo flüt ve üçgen ile', 'Yalnızca perdesiz rebec ve tambur ile'], 'Soprano partilerini üstlenen bir-iki parlak kornetto ile alto, tenor ve bas partilerini çalan sackbut\'lar (örneğin Gabrieli, Monteverdi ve Schütz\'ün eserlerinde) dönemin en soylu kilise üflemeli konsortuydu.'),
  ('17. yüzyıl Alman kentlerinde belediye meclisi tarafından istihdam edilen, saat kulelerinden koraller çalan, düğün ve kent törenlerinin hem üflemeli hem yaylı müziğini üstlenen resmi şehir müzisyenleri loncasına ne ad verilirdi?', 'Stadtpfeifer', ['Minnesänger', 'Castrati', 'Camerata'], 'J. S. Bach\'ın babası Johann Ambrosius Bach gibi pek çok aile üyesinin de mensup olduğu \'Stadtpfeifer\' (şehir üflemecileri/çalgıcıları), çok sayıda çalgıyı ustalıkla çalmak zorunda olan kent lonca müzisyenleriydi.'),
  ('Barok dönemde yaylı veya üflemeli bir solistin uzun tutulan tek bir notaya çok hafif başlayıp giderek gürleştirmesi ve ardından yeniden yumuşatarak bitirmesiyle ( < > ) ses kontrolünü sergilediği anlatım tekniği hangisidir?', 'Messa di voce', ['Bariolage', 'Pizzicato', 'Staccato'], 'Şan sanatından (özellikle Caccini ve kastrato geleneğinden) Barok keman ve üflemeli icrasına geçen \'messa di voce\' (sesin yerleştirilmesi), tek nota üzerinde şişip sönerek yapılan en üst düzey ifade süslemesidir.'),
  ('Erken Barok çalgı müziğinde Claudio Monteverdi\'nin 1624 tarihli \'Il combattimento di Tancredi e Clorinda\' eserinde savaş öfkesini yansıtmak için ilk kez kuramsallaştırıp yaylılara uygulattığı iki yeni teknik nedir?', 'Hızlı on altılık nota tekrarıyla \'concitato\' (tremolo benzeri heyecan) ve teli parmakla çekme', ['Yayın ahşap sırtıyla vurma ve keman gövdesini alkışlama', 'Çalgıyı baş aşağı çevirip yalnızca çene ucuyla çalma', 'Dört teli aynı anda gevşeterek glissando uğultusu çıkarma'], 'Monteverdi, savaşçı öfke duygusunu (\'stile concitato\') betimlemek için aynı notanın yayla on altı kez hızla tekrarlanmasını ve kılıç çarpışması için yayın bırakılıp tellerin iki parmakla çekilmesini (pizzicato) notaya dökmüştür.'),
  ('Tarihsel Barok icra pratiğinde (HIP – Historically Informed Performance) modern senfoni orkestrası çalgıları yerine dönem çalgılarının kopyalarının tercih edilmesinin temel sanatsal amacı nedir?', 'Bağırsak tel, ahşap üflemeli ve doğal bakırların şeffaf tını dengesiyle Barok artikülasyon ve kontrpuan berraklığını yakalamak', ['Konser salonlarında mikrofon kullanmadan yüz yirmi desibellik ses şiddetine ulaşmak', 'Eserlerin temposunu yarı yarıya düşürerek senfonik ağırlık kazandırmak', 'Bestecilerin yazdığı tüm süslemeleri silerek yalın iskelet bırakmak'], '20. yüzyılda Arnold Dolmetsch, Gustav Leonhardt ve Nikolaus Harnoncourt gibi öncülerle gelişen tarihsel bilinçli icra, dönem çalgılarının şeffaf ve konuşur gibi (retorik) tınısını yeniden canlandırmıştır.'),
  ('Barok estetiğindeki \'Duygular Öğretisi\' (Affektenlehre) ilkesine göre tek bir arya veya konçerto bölümünün duygusal akışı nasıl kurgulanmalıdır?', 'Bölüm boyunca tek bir temel duygu durumunu (neşe, keder, öfke vb.) tutarlı biçimde işleyip sürdürmelidir', ['Her dört ölçüde bir neşeden trajediye sıçrayan öngörülemez ruhsal çalkantılar sergilemelidir', 'Bestecinin o günkü özel günlük acılarını dinleyiciden gizleyen soyut şifreler taşımalıdır', 'Duygusal ifadeyi tamamen reddedip yalnızca soğuk geometrik oranları duyurmalıdır'], 'Descartes\'ın \'Ruhun Tutkuları\' felsefesinden beslenen Affektenlehre anlayışında her bölüm tek bir \'affetto\'yu (duygu halini) belirli ritmik ve ezgisel figürlerle baştan sona temsil eder.'),
  ('1600 yılı dolaylarında kuramcı Giovanni Maria Artusi\'nin Monteverdi\'nin madrigallerindeki hazırlıksız uyumsuz sesleri eleştirmesi üzerine Monteverdi, eski kurallı polifoni ile kendi yeni dramatik üslubunu hangi terim çiftiyle ayırmıştır?', 'Prima prattica ve Seconda prattica', ['Ars Antiqua ve Ars Nova', 'Sonata da chiesa ve Sonata da camera', 'Opera seria ve Opera buffa'], 'Monteverdi\'ye göre Palestrina\'nın temsil ettiği \'prima prattica\'da müzik sözün efendisidir; kendisinin \'seconda prattica\'sında ise şiirsel söz müziğin efendisidir (l\'orazione sia padrona dell\'armonia) ve uyumsuzlukları meşru kılar.'),
  ('Rönesans\'ın eşit sesli polifonisinden Barok dönemin \'monodi\' üslubuna geçişte müzik dokusunda yaşanan en köklü değişim nedir?', 'Tek bir duygulu solo vokal çizginin en üste çıkıp sürekli bas akorlarıyla alttan desteklendiği kutuplu dokunun doğması', ['Bütün çalgıların ve akorların kaldırılıp Gregoryen çağındaki çalgısız tek sesliliğe dönülmesi', 'Sekiz ayrı koronun kilise kubbesinin dört köşesinden aynı anda farklı dillerde bağırması', 'Melodinin tamamen en pes bas partisine verilip üst seslerin sessiz bırakılması'], 'Erken Barok monodi (Caccini\'nin Le nuove musiche\'si), şiirin anlaşılırlığı ve bireysel duygu aktarımı için \'tizde özgür solo ezgi + en altta sağlam sürekli bas\' (dış seslerin kutuplaşması) ilkesini kurmuştur.'),
  ('İtalyanca \'concertare\' (hem yarışmak/çekişmek hem uzlaşmak) kökünden türeyen Barok \'concertato üslubu\'nun temel estetik ilkesi nedir?', 'Farklı ses ve çalgı gruplarının tını, gürlük ve doku bakımından karşıtlık kurarak nöbetleşe ve birlikte tınlaması', ['Bütün çalgıların baştan sona tek bir ezgiyi hiçbir armoni olmadan ünison çalması', 'Eserlerin yalnızca halka açık biletli akşam konserlerinde seslendirilmesi', 'İcracıların sahneye çıkmadan önce çalgılarını tek bir diyapazon çatalıyla eşitlemesi'], 'Barok müziğin kalbi olan \'stile concertato\', insan sesleri ile çalgıları veya küçük grupla büyük grubu renkli bir rekabet ve işbirliği içinde karşı karşıya getirir.'),
  ('Bir fügün serim (exposition) kesitinde birinci ses eksen tonda özneyi bitirdikten hemen sonra ikinci sesin aynı temayı hangi tonal derecede devralarak \'yanıt\' (answer / comes) vermesi kuraldır?', 'Beşli yukarıdaki (veya dörtlü aşağıdaki) dominant tonunda', ['Yarım ses yukarıdaki uzak Napoliten derecesinde', 'Üç oktav aşağıdaki alt-kontrbas bölgesinde', 'Tam dörtlü eksiltilmiş tritonus derecesinde'], 'Füg seriminde özne (dux) tonik derecesinde başlar, hemen ardından ikinci ses (comes / yanıt) temayı dominant (beşli) derecesinde duyurarak tonal dengeyi kurar.'),
  ('Fügde ikinci ses \'yanıt\'ı seslendirmeye başladığında birinci sesin susmayıp yanıtın karşısında her seferinde düzenli olarak tekrarlanan karakteristik bir eşlik ezgisi örmesine ne ad verilir?', 'Karşı-özne', ['Alberti bası', 'Serbest kadans', 'Şifreli arpej'], 'Öznenin ve yanıtın her girişinde onunla ters/tamamlayıcı kontrpuan kuran sabit ikinci tematik çizgiye \'karşı-özne\' (kontrasujet) adı verilir.'),
  ('Bir fügün içinde öznenin bütünüyle duyurulmadığı, bunun yerine özne motiflerinden türetilen sekanslarla bir tondan diğerine geçiş sağlayan rahatlatıcı ara kesitlere ne ad verilir?', 'Ara oyun / Divertimento', ['Stretto sıkıştırması', 'Da capo dönüşü', 'Ripieno girişi'], 'Fügde tam tema girişlerinin (orta serimlerin) arasına yerleştirilen ve çoğunlukla modülan sekanslarla ilerleyen köprü kesitlerine \'episode\' veya \'divertimento\' denir.'),
  ('Fügün özellikle doruk noktasına yaklaşılan son kesitlerinde, bir ses özneyi henüz tamamlamadan diğer sesin sabırsızca üst üste binerek özneyi girmesiyle gerilimin tırmandırılmasına ne denir?', 'Stretto', ['Diminuendo', 'Ostinato', 'Rallentando'], 'İtalyanca \'daraltılmış/sıkıştırılmış\' anlamına gelen \'stretto\', tema girişleri arasındaki zaman mesafesini kısaltarak nefes kesici bir kontrpuan yoğunluğu yaratır.'),
  ('Füg yazısında öznenin tüm nota sürelerinin iki katına çıkarılarak ağırbaşlı biçimde duyurulması ile sürelerin yarıya indirilerek hızlandırılması sırasıyla hangi terimlerle ifade edilir?', 'Büyütme (Augmentation) ve Küçültme (Diminution)', ['Ters çevirme (Inversion) ve Geriye okuma (Retrograde)', 'Senkopasyon ve Noktalama', 'Transpozisyon ve Modülasyon'], 'Kontrpuan sanatında ritmik değerlerin oranlı olarak genişletilmesine \'augmentation\' (büyütme), daraltılmasına ise \'diminution\' (küçültme) adı verilir.'),
  ('Bir fügün sonuna yaklaşırken bas partisinin (çoğu kez org pedalında) uzun ölçüler boyunca dominant veya tonik notasını aralıksız tutması ve üst seslerin bunun üzerinde zengin uyumsuzluklarla çözülmesine ne ad verilir?', 'Pedal noktası', ['Yarım kadans durağı', 'Tasto solo boşluğu', 'Bariolage geçişi'], 'Org icracısının ayağını tek bir pedal tuşuna basılı tutmasından adını alan \'pedal noktası\' (orgelpunkt), tonal merkeze güçlü dönüş gerilimi yaratan temel Barok mimari araçtır.'),
  ('Barok dönemde bir fügün hemen önünde yer alan \'prelüd\', \'toccata\' veya \'fantazi\' bölümlerinin füg ile kurduğu estetik denge aşağıdakilerden hangisidir?', 'Özgür, doğaçlama karakterli ve virtüöz pasajlarla icracıyı/dinleyiciyi hazırlayıp ardından gelen sıkı kurallı füg ile karşıtlık oluşturması', ['Fügdeki tüm temaları tam olarak aynı kontrpuan kurallarıyla iki kez önceden tekrar etmesi', 'Sözlü bir koro ilahisi olarak söylenip füg başladığında çalgıların susmasını sağlaması', 'Yalnızca vurmalı çalgılarla ritim vererek dansçıların sahneye girmesini beklemesi'], 'İtalyanca \'toccare\' (dokunmak) kökünden gelen toccata, fantazi ve prelüd; parmakları ısıtan özgür ve rapsodik doğasıyla fügün sıkı entelektüel disiplinine kusursuz bir denge kurar.'),
  ('Barok vokal müziğinde (Monteverdi, Cavalli, Purcell ve Bach\'ta) derin keder, ölüm ve trajik veda sahnelerini simgeleyen \'ağıt bası\' (lamento bass) hangi ezgisel hareketle tanınır?', 'Tonik sesinden dominant sesine (dörtlü aralık boyunca) ağır adımlarla diyatonik veya kromatik olarak inen bas yürüyüşüyle', ['Üç oktav boyunca arpejlerle hızla yukarı fırlayan neşeli majör borazan figürüyle', 'Aksak yedi zamanlı halk dansı ritmiyle zıplayan staccato oktavlarla', 'Yalnızca tam beşli aralıklarla paralel yürüyen Orta Çağ organum kalıbıyla'], '1. dereceden 5. dereceye ağır ağır çöken kromatik dörtlü yürüyüşü (\'passus duriusculus\' / lamento bass), Dido\'nun Ağıtı ve Bach\'ın \'Crucifixus\'u gibi başyapıtların evrensel keder simgesidir.'),
  ('Barok müziğin üçlü ölçüdeki iki kardeş ostinato çeşitleme formu olan ve Bach\'ın Do minör Org eseri ile Re minör Solo Keman Partitası\'nın dev finalini oluşturan tür çifti hangisidir?', 'Passacaglia ve Chaconne', ['Gavotte ve Bourrée', 'Allemande ve Gigue', 'Toccata ve Prelüd'], 'İspanyol-Yeni Dünya kökenli üçlü zamanlı ağır çeşitleme formları olan Passacaglia (genellikle belirgin melodik bas teması üzerine) ve Chaconne (tekrarlanan akor yürüyüşü üzerine) Barok mimarinin zirveleridir.'),
  ('Vivaldi ile standartlaşan üç bölümlü Barok \'solo konçerto\'nun birinci ve üçüncü (hızlı) bölümlerinde orkestranın ana temayı farklı tonlarda geri getirip solistin parlak ara pasajlarıyla nöbetleştiği form hangisidir?', 'Ritornello formu', ['Sonat allegrosu formu', 'İkili dans formu', 'Bar formu'], '\'Küçük dönüş\' anlamına gelen ritornello formunda tutti orkestranın çaldığı kararlı tema (ritornello) yakın tonlara uğrayarak sütunlar kurar, solist ise bu sütunlar arasında virtüöz epizotlarla uçar.'),
  ('Barok süitin çekirdek danslarından \'Allemande\'ın ölçü, tempo ve başlangıç karakteri nasıldır?', 'Dört dörtlük (ikili) ölçüde, orta-ağırbaşlı hızda, kısa bir eksik ölçü (anakruz) ile başlayıp kesintisiz on altılık akış sergileyen Alman kökenli dans', ['Üç sekizlik çok hızlı ölçüde, güçlü birinci vuruş vurgusuyla fırlayan İskoç sıçrama dansı', 'Üç dörtlük ağır tempoda, ikinci vuruşu uzatılarak noktalı vurgulanan törensel İspanyol dansı', 'Altı sekizlik bileşik ölçüde, noktalı kayıkçı ritmiyle sallanan Sicilya çoban dansı'], 'Fransızcada \'Alman dansı\' anlamına gelen Allemande, 4/4 ölçüde ciddi, akıcı ve zengin kontrpuan/kırık akor dokulu açılış dansıdır.'),
  ('Barok süitte üçüncü sırada yer alan İspanyol/Latin Amerika kökenli \'Sarabande\' dansını diğer bölümlerden hemen ayırt ettiren ritmik özellik nedir?', 'Ağır ve asil üçlü ölçüde ilerlerken vurgunun ve uzun sürenin sıklıkla ikinci vuruş üzerinde yoğunlaşması', ['Her ölçünün tam ortasında yarım ölçülük ani sessizlikler bulunması', 'İkili ölçüde askeri trampet ritmiyle baştan sona çok hızlı koşması', 'Yalnızca pizzicato tekniğiyle yedi sekizlik aksak ölçüde çalınması'], 'Başlangıçta Yeni Dünya ve İspanya\'da hızlı ve kışkırtıcı bir dansken Fransa ve Almanya\'da ağırlaştırılan Sarabande (örneğin Handel\'in Re minör Sarabande\'ı), 2. vuruşa binen vakur ağırlığıyla süitin duygusal kalbidir.'),
  ('Barok süit bölümlerinin hemen hemen tümünde (Allemande, Courante, Sarabande, Gigue) kullanılan standart \'ikili form\' (AABB) içindeki tonal yolculuk nasıl gerçekleşir?', 'A bölmesi tonikten başlayıp dominant (veya ilgili majör) tonuna modülasyon yapar; B bölmesi ise bu yeni tondan yola çıkıp tekrar ana toniğe döner', ['A bölmesi ana tonda başlayıp biterken B bölmesi tamamen rastgele uzak bir tonda sona erer', 'Her iki bölme de hiçbir değiştirici işaret almadan baştan sona aynı akor üzerinde sabit kalır', 'A bölmesi minör tonda yazılıp B bölmesinde tüm çalgılar susturularak sözlü aryaya geçilir'], 'Barok iki bölmeli (binary) dans formunun simetrik tonal yayı (I -> V :||: V -> I veya minörde i -> III :||: III/v -> i), daha sonra Klasik dönem sonat allegrosu formunun çekirdeğini oluşturmuştur.'),
  ('Barok oda müziğinin en gözde türü olan \'trio sonat\' (üçlü sonat), tipik bir konserde kaç müzisyen tarafından seslendirilir ve neden bu sayı ortaya çıkar?', 'Dört müzisyenle; çünkü iki üst ezgi çalgısına ek olarak \'sürekli bas\' partisini hem bir çello/gamba hem de bir klavsen/org birlikte çalar', ['Üç müzisyenle; çünkü sürekli bas partisinde klavyeli çalgı kullanılması kurallarca yasaklanmıştır', 'Altı müzisyenle; çünkü her yazılı nota partisini ikişer kemancının çiftleyerek çalması zorunludur', 'İki müzisyenle; çünkü klavsenci ayaklarıyla üçüncü partiyi çalarken tek kemancı iki tel çalar'], '\'Trio sonat\' adı icracı sayısını değil partisyondaki üç yazılı çizgiyi (örneğin iki keman + basso continuo) belirtir; sürekli bas grubu iki kişiden (çello + klavsen/org) oluştuğu için sahnede 4 icracı yer alır.'),
  ('Arcangelo Corelli ile klasikleşen Barok \'sonata da chiesa\' (kilise sonatı) ile \'sonata da camera\' (oda sonatı) arasındaki yapısal fark aşağıdakilerden hangisidir?', 'Kilise sonatı ağır–hızlı–ağır–hızlı tempolu ciddi kontrpuan bölümlerinden oluşurken, oda sonatı bir prelüd ve peş peşe stilize dans başlıklarından oluşur', ['Kilise sonatında yalnızca vurmalı çalgılar yer alırken oda sonatında dev koro ilahileri söylenir', 'Kilise sonatı tek bölümlük hızlı bir rondo iken oda sonatı iki saatlik sahneli bir operadır', 'Kilise sonatında klavsen zorunluyken oda sonatında yalnızca büyük katedral orgu kullanılır'], 'Sonata da chiesa (örneğin Corelli Op. 1 ve Op. 3) dans adları taşımayan ciddi 4 bölümlü (Grave–Allegro–Adagio–Allegro) yapısıyla org eşliğinde kiliseye uygunken; sonata da camera (Op. 2 ve Op. 4) klavsenli bir oda süitidir.'),
  ('Jean-Baptiste Lully\'nin XIV. Louis sarayı için standartlaştırdığı ve Handel ile Bach\'ın da sıkça kullandığı iki kesitli \'Fransız uvertürü\'nün yapısal planı nasıldır?', 'Noktalı keskin ritimlerle ilerleyen görkemli ve ağır bir açılış bölmesi, ardından hızlı ve taklitli (fügal) canlı bir ikinci bölme', ['Çok hızlı bir fırtına girişi, ortada lirik bir flüt solosu ve sonda gürültülü bir marş', 'Eşliksiz tek bir trompet çağrısının ardından gelen ağırbaşlı sarabande ve minuet dizisi', 'Koro tarafından söylenen bir dua ve onu izleyen komik halk dansı çeşitlemeleri'], 'Kralın salona girişindeki ihtişamı simgeleyen Fransız uvertürü, karakteristik abartılı noktalı ritimli ağır (Grave/Maestoso) açılışı ve onu izleyen enerjik fügal (Allegro) bölmesiyle (bazen sonda ağır açılışa kısa dönüşle) tanınır.'),
  ('Alessandro Scarlatti ve Napoli opera okulunun yaygınlaştırdığı üç kesitli \'İtalyan uvertürü\' (sinfonia), müzik tarihinde hangi büyük klasik formun doğrudan atası kabul edilir?', 'Klasik dönem çok bölümlü senfonisinin', ['Solo piyano noktürnünün', 'Romantik dönem sanat şarkısının', 'Orta Çağ litürjik dramının'], 'Operaların başında çalınan Hızlı – Yavaş – Hızlı (Allegro – Andante – Presto) yapısındaki İtalyan opera \'sinfonia\'sı, zamanla operadan kopup konser salonunda bağımsızlaşarak klasik senfoniyi doğurmuştur.'),
  ('Geç Barok operasının ve kantatlarının en egemen solo vokal formu olan \'da capo arya\'da şarkıcının ustalığını (virtüözitesini) asıl sergilediği an neresidir?', 'B bölmesi bittikten sonra \'baştan\' (da capo) işaretiyle tekrarlanan A bölmesini kendi doğaçlama süslemeleri ve kadanslarıyla zenginleştirdiği kısım', ['Eser başlamadan önce orkestra akort yaparken sahne arkasından attığı tiz çığlık', 'Orkestranın tamamen sustuğu kuru resitatif (secco) konuşmalarındaki hızlı hecelemeler', 'Perde kapandıktan sonra koro ile birlikte hep bir ağızdan söylediği sade ilahi'], 'ABA şemalı \'da capo\' aryada ilk A bölmesi bestecinin yazdığına yakın okunur; B karşıtlığından sonra A\'ya dönüldüğünde ise solistin ezgiyi parlak koloraturlar ve doğaçlama bezemelerle yeniden yaratması beklenirdi.'),
  ('Barok vokal müziğinde kuru resitatifin serbest konuşma akışı ile aryanın düzenli ölçülü şarkısallığı arasında duran, kısa ve duygulu ara solo kesitlere hangi ad verilir?', 'Arioso', ['Ritornello', 'Sinfonia', 'Cabaletta'], 'Özellikle Bach\'ın pasyonlarında ve Monteverdi\'den Handel\'e operalarda resitatifin ortasında aniden çiçek açan ölçülü ve lirik şarkımsı kesitlere \'arioso\' denir.'),
  ('Protestan Alman kilise müziğinde cemaatin bildiği bir koral ezgisinin orgcu tarafından ayin sırasında söylenmeden önce kontrpuan ve süslemelerle işlenerek sunulduğu kısa solo org türüne ne ad verilir?', 'Koral prelüd', ['Konçerto grosso', 'Madrigal komedisi', 'Sonata da camera'], 'Pachelbel, Buxtehude ve J. S. Bach\'ın yüzlerce başyapıt verdiği \'koral prelüd\', cemaate hem ilahinin tonunu ve ezgisini hatırlatır hem de ilahinin sözlerindeki teolojik anlamı orgda yorumlar.'),
  ('Barok müzikal retorik figürleri arasında yarım ses aşağı inen iki notalık bağlı motif (\'pianto\' / iç çekiş figürü) dinleyicide hangi duyguyu uyandırmak için kullanılırdı?', 'Gözyaşı, inilti ve derin keder duygusunu', ['Askeri zafer coşkusunu ve borazan çağrısını', 'Köylü düğünlerindeki neşeli kahkahaları', 'Fırtınalı denizdeki şimşek çakışlarını'], 'İtalyanca \'ağlayış\' anlamına gelen \'pianto\' (küçük ikili aşağı çözülme), erken operadan Bach\'a ve hatta Mozart\'a kadar acı ve iç çekişin evrensel sembolü olmuştur.'),
  ('6/8 veya 12/8 ölçüde, yumuşak sallantılı noktalı ritmi ve neapoliten altılı armonileriyle Barok aryalar ve sonat yavaş bölümlerinde pastoral huzur veya tatlı hüzün yaratan Güney İtalya kökenli form hangisidir?', 'Siciliana', ['Tarantella', 'Bourrée', 'Hornpipe'], 'Handel\'in pastoral aryalarından Bach\'ın \'Erbarme dich\' aryası ve flüt sonatlarına kadar pek çok Barok başyapıt, beşik gibi sallanan \'uzun-kısa-uzun\' üçüzlü \'Siciliana\' ritmine dayanır.'),
  ('Rönesans\'ın sekiz/on iki kilise moduna dayalı yatay sisteminin 17. yüzyıl sonuna doğru yerini Barok \'işlevsel tonalite\'ye bırakması ne anlama gelir?', 'Müziğin yirmi dört majör ve minör tonda eksen (tonik), çeken (dominant) ve altçeken (subdominant) akor çekim güçleri etrafında yön kazanması', ['Diyez ve bemol işaretlerinin tümüyle kaldırılarak yalnız beyaz tuşlarda müzik yapılması', 'Akor kavramının terk edilip ezgilerin rastgele çeyrek ses aralıklarıyla dizilmesi', 'Bütün eserlerin yalnızca Re karar sesinde başlayıp Mi sesinde bitirilmesi'], 'Corelli\'nin sonat ve konçertolarıyla kristalleşen majör-minör tonal sistem, beşliler çemberi üzerindeki modülasyonları ve V–I çekim kuvvetini büyük ölçekli Barok formların motoru haline getirmiştir.'),
  ('Barok füg türleri arasında iki ayrı temanın eserin başından itibaren birlikte veya ayrı serimlerden sonra eşzamanlı olarak kusursuz kontrpuanda birleştirildiği yapıya ne ad verilir?', 'Çift füg (Double fugue)', ['Yarım füg (Fughetta)', 'Sahte girişli füg', 'Tek sesli prelüd'], 'İki bağımsız özneye sahip füglere \'çift füg\', üç bağımsız öznenin en sonunda görkemli biçimde üst üste birleştiği (örneğin Bach\'ın Mi bemol majör \'St. Anne\' Org Fügü) yapılara ise \'üçlü füg\' denir.'),
  ('Bir füg veya süit bölümünün içine füg karakterli kısa bir kesit yerleştirildiğinde, tam ölçekli bir füg olmaksızın yalnızca serim benzeri taklitli girişler yapan bu tekniğe hangi ad verilir?', 'Fugato', ['Ostinato', 'Pizzicato', 'Portato'], 'Bağımsız bir füg olmayıp başka bir formun (uvertür, sonat, arya veya senfoni) akışı içinde beliren fügal pasajlara \'fugato\' denir; küçük boyutlu sevimli füglere ise \'fughetta\' adı verilir.'),
  ('Fransız Barok klavsen süitlerinde (Couperin ve Rameau) sıkça kullanılan, \'ABACADA...\' biçiminde zarif bir ana bölmenin (\'refrain\') her defasında farklı \'couplet\' kesitleriyle nöbetleştiği form hangisidir?', 'Rondeau', ['Passacaglia', 'Ricercar', 'Allemande'], 'Orta Çağ şiir formundan Barok klavsen müziğine evrilen Fransız \'rondeau\'su (örneğin Couperin\'in Les Barricades Mystérieuses eseri), değişmeden dönen nakaratı ve ara kupleleriyle klasik rondo formunun öncüsüdür.'),
  ('Floransa Camerata\'sı üyesi kuramcı ve lavtacı Vincenzo Galilei\'nin 1581 tarihli \'Dialogo della musica antica, et della moderna\' adlı incelemesiyle Rönesans kontrpuanına yönelttiği temel eleştiri neydi?', 'Farklı seslerin aynı anda başka kelimeler söyleyerek şiirin duygusal anlamını bozması', ['Kilise orglarının bakır üflemeli çalgılarla birlikte çok gürültülü marşlar çalması', 'Bütün vokal eserlerin yalnızca tek bir karar perdesi etrafında hareketsiz kalması', 'Şarkıcıların sahnede maske takarak İtalyanca yerine Latince dizeler okuması'], 'Ünlü astronom Galileo Galilei\'nin babası olan Vincenzo Galilei, dört-beş sesli karmaşık polifoninin metni anlaşılmaz hale getirdiğini savunarak Antik Yunan\'daki tek sesli duygusal söylevi örnek göstermiştir.'),
  ('1602 yılında yayımladığı \'Le nuove musiche\' (Yeni Müzikler) adlı solo madrigal ve arya derlemesiyle erken Barok monodi üslubunun kurallarını ve şan süslemelerini sistemleştiren besteci kimdir?', 'Giulio Caccini', ['Giovanni Pierluigi da Palestrina', 'Baldassare Galuppi', 'Domenico Cimarosa'], '\'Amarilli, mia bella\' adlı ölümsüz aryasıyla da tanınan Giulio Caccini, \'Le nuove musiche\'nin önsözünde sesin tutkuyla şişirilip azaltılması ve zarif boğaz süslemeleri üzerine temel ilkeler koymuştur.'),
  ('Monteverdi\'nin 1608\'de bestelediği \'L\'Arianna\' operasının tamamı kaybolmuş olmasına karşın tek başına kurtulup 17. yüzyıl boyunca sayısız besteciye örnek olan ünlü solo sahnesi hangisidir?', 'Lamento d\'Arianna', ['Tancredi ve Clorinda\'nın Düellosu', 'Poppea\'nın Taç Giyme Düeti', 'Orfeo\'nun Trakya Çobanları Korosu'], 'Terk edilen Arianna\'nın \'Lasciatemi morire!\' (Bırakın öleyim!) çığlığıyla başlayan \'Arianna\'nın Ağıtı\', dinleyicileri gözyaşlarına boğmuş ve Barok operadaki trajik ağıt sahnelerinin arketipi olmuştur.'),
  ('Claudio Monteverdi\'nin 1610 yılında Papa V. Paulus\'a ithaf ederek yayımladığı, hem Rönesans polifonisini hem de gösterişli yeni Venedik concertato üslubunu görkemli bir sentezde buluşturan kutsal başyapıtı hangisidir?', 'Vespro della Beata Vergine', ['Membra Jesu Nostri kantat dizisi', 'Musikalische Exequien cenaze töreni', 'Fiori musicali org ayinleri kitabı'], 'Monteverdi\'nin \'Kutsal Bakire\'nin Akşam Duaları\' (1610 Vespers), eski cantus firmus tekniği ile yankılı solo kemanlar, kornettolar ve çift korolu ihtişamı birleştiren anıtsal bir başyapıttır.'),
  ('Monteverdi\'nin 1643\'te Venedik için yetmiş beş yaşındayken bestelediği son operası \'L\'incoronazione di Poppea\', konusunu mitoloji yerine nereden almasıyla opera tarihinde bir dönüm noktası olmuştur?', 'Roma İmparatoru Neron dönemindeki gerçek tarihi olaylardan', ['Orta Çağ Haçlı Seferleri sırasındaki büyücü efsanelerinden', 'Antik Yunan tanrılarının Olimpos Dağı\'ndaki şölenlerinden', 'Tevrat\'ta anlatılan Babil sürgünü ve tapınak kıssalarından'], 'Busenello\'nun librettosuyla yazılan \'Poppea\'nın Taç Giymesi\', mitolojik masallar yerine ihtiras, entrika ve ahlaki belirsizliklerle dolu gerçek Roma tarihini sahneye taşıyan ilk büyük operadır.'),
  ('Monteverdi\'nin 1587 ile 1638 yılları arasında yayımladığı \'Sekiz Madrigal Kitabı\' müzik tarihi açısından hangi büyük evrimi adım adım belgeler?', 'Eşliksiz Rönesans polifonisinden sürekli baslı ve çalgılı dramatik Barok üsluba geçişi', ['Alman kilise koralinden dört bölümlü klasik senfoni orkestrasına geçişi', 'Fransız saray balesinden İspanyol gitar çeşitlemelerine yönelişi', 'Tek sesli Gregoryen ilahisinden on iki tonlu atonal müziğe sıçrayışı'], 'Monteverdi ilk dört kitabında eşliksiz Rönesans madrigalini zirveye taşırken, 5. kitaptan itibaren sürekli bası zorunlu kılmış ve 8. kitapta (\'Savaş ve Aşk Madrigalleri\') tam teşekküllü dramatik Barok sahnelere ulaşmıştır.'),
  ('1625 yılında Floransa\'da sahnelenen \'La liberazione di Ruggiero dall\'isola d\'Alcina\' adlı eseriyle müzik tarihinde operası bilinen ilk kadın besteci olma unvanını taşıyan sanatçı kimdir?', 'Francesca Caccini', ['Hildegard von Bingen', 'Maddalena Casulana', 'Élisabeth Jacquet de La Guerre'], 'Giulio Caccini\'nin kızı olup Medici sarayının en yüksek ücretli müzisyeni konumuna yükselen \'La Cecchina\' lakaplı Francesca Caccini, bu bale-operasını Polonya Prensi Władysław onuruna bestelemiştir.'),
  ('17. yüzyıl Venedik\'inde opera sahnesine çıkmaksızın kendi adıyla sekiz cilt solo arya, madrigal ve dünyevi kantat yayımlayarak Barok dönemin en üretken basılı bestecilerinden biri olan kadın sanatçı kimdir?', 'Barbara Strozzi', ['Francesca Lebrun', 'Nannerl Mozart', 'Fanny Mendelssohn'], 'Şair Giulio Strozzi\'nin evlatlık kızı ve Venedik entelektüel akademilerinin yıldız sopranosu Barbara Strozzi (1619–1677), yoğun duygusal ifadeli dünyevi \'cantata\' türünün en seçkin ustalarındandır.'),
  ('Roma\'daki Aziz Petrus Bazilikası\'nın baş orgcusu olarak otuz bin kişiyi dinlemeye çekecek kadar ün kazanan ve \'Fiori musicali\' (Müzikal Çiçekler, 1635) adlı org ayinleri derlemesi J. S. Bach tarafından elle kopyalanan İtalyan usta kimdir?', 'Girolamo Frescobaldi', ['Domenico Zipoli', 'Baldassare Galuppi', 'Giovanni Paisiello'], 'Erken Barok klavye müziğinin devi Frescobaldi, rapsodik toccata\'ları, kromatik ricercar\'ları ve \'Fiori musicali\'siyle Güney ve Kuzey Alman org okulunu (Froberger ve Bach) derinden etkilemiştir.'),
  ('17. yüzyıl ortasında Roma\'da Latince İncil öykülerine dayalı kutsal \'oratoryo\' türünü olgunlaştıran ve kızını kurban etmek zorunda kalan komutanın trajedisini anlattığı \'Jephte\' oratoryosuyla tanınan besteci kimdir?', 'Giacomo Carissimi', ['Antonio Caldara', 'Nicola Porpora', 'Leonardo Vinci'], 'Roma\'daki Alman Koleji başmüzisyeni Giacomo Carissimi, sahnesiz İncil dramlarında koroya güçlü bir dramatik rol vermiş ve \'Jephte\'nin sonundaki dokunaklı altılı ağıt korosuyla çağdaşlarını büyülemiştir.'),
  ('Arcangelo Corelli\'nin 1700 tarihli Op. 5 Solo Keman Sonatları dizisinin on ikinci ve son eseri, İber Yarımadası kökenli hangi ünlü on altı ölçülük ostinato tema üzerine yazılmış yirmi üç parlak çeşitlemeden oluşur?', 'La Folia', ['Greensleeves ezgisi', 'L\'homme armé şarkısı', 'Dies irae sekansı'], 'Portekiz-İspanyol kökenli çılgın saray dansı teması \'La Folia\', Corelli\'nin Op. 5 No. 12 sonatındaki görkemli keman çeşitlemeleriyle Lully\'den Vivaldi ve Rachmaninoff\'a uzanan geleneğin en ünlü halkası olmuştur.'),
  ('Arcangelo Corelli\'nin Op. 6 No. 8 Sol minör Konçerto Grosso\'sunun sonuna \'Fatto per la notte di Natale\' (Noel gecesi için yapılmıştır) notuyla eklediği huzurlu kapanış bölümü hangi başlığı taşır?', 'Pastorale', ['Marcia funebre', 'Fuga doppia', 'Capriccio eroico'], 'Beytlehem\'deki çobanların gayda ezgilerini taklit eden 12/8\'lik yumuşak \'Pastorale ad libitum\' bölümü, Corelli\'nin Noel Konçertosu\'nu Barok repertuvarın en sevilen eserlerinden biri yapmıştır.'),
  ('Venedikli zengin bir kâğıt tüccarı aileden geldiği için kendini başlangıçta \'dilettante Veneto\' (Venedikli amatör) diye tanıtan, özellikle lirik \'Obua Konçertoları\' (Op. 7 ve Op. 9) J. S. Bach\'ın bile füg temalarına esin veren besteci kimdir?', 'Tomaso Albinoni', ['Giacomo Carissimi', 'Girolamo Frescobaldi', 'Francesco Landini'], 'Tomaso Albinoni (1671–1751) elliden fazla opera ve seçkin obua konçertoları yazmıştır; ancak bugün \'Albinoni Adagio\' diye bilinen ünlü Sol minör eser aslında 1945\'te müzikolog Remo Giazotto tarafından küçük bir bas taslağından bestelenmiştir.'),
  ('Antonio Vivaldi\'nin otuz yılı aşkın süre keman öğretmenliği ve konser yöneticiliği yaptığı, tamamı terk edilmiş veya yetim kız çocuklarından oluşan dünyaca ünlü Venedik kurumu hangisidir?', 'Ospedale della Pietà', ['Accademia Filarmonica di Bologna', 'Teatro alla Scala Operası', 'Collegium Germanicum Roma'], 'Venedik\'teki dört hayır kurumundan biri olan Ospedale della Pietà, kız öğrencilere en üst düzey müzik eğitimi veriyor; parmaklıklar ardından verdikleri konserleri dinlemeye tüm Avrupa\'dan gezginler geliyordu.'),
  ('Vivaldi\'nin 1711\'de Amsterdam\'da yayımlanan ve J. S. Bach\'ın altı tanesini hayranlıkla klavsen ve org için uyarladığı on iki konçertoluk çığır açıcı Op. 3 koleksiyonunun başlığı nedir?', 'L\'estro armonico', ['L\'arte del violino', 'Les Goûts-réunis', 'Tafelmusik koleksiyonu'], '\'Armonik İlham\' anlamına gelen \'L\'estro armonico\' Op. 3 (bir, iki ve dört keman konçertoları), tüm Avrupa\'da İtalyan ritornello konçerto çılgınlığını başlatan en etkili Barok yayınıdır.'),
  ('Vivaldi, \'Dört Mevsim\' konçertolarında dinleyicinin ve icracının hangi ölçüde kuş cıvıltısı, çoban köpeği havlaması, uyuklayan sarhoş veya diş takırdaması betimlendiğini tam olarak anlaması için partisyona ne eklemiştir?', 'Her konçertonun başına muhtemelen kendisinin yazdığı açıklayıcı birer İtalyanca sone', ['Sahne önünde sessiz pandomim yapacak dansçılar için kareografi çizimleri', 'Orkestra şefinin her bölüm başında yüksek sesle okuyacağı Latince dualar', 'Kemanların ses deliğine yapıştırılan renkli mevsim manzarası gravürleri'], 'Vivaldi her mevsim konçertosunun başına on dört dizelik açıklayıcı bir sone koymuş ve şiirdeki dizeleri harflerle partisyondaki ilgili ölçülerin (örneğin İlkbahar Largo\'da havlayan köpeği çalan viyolanın) tam üstüne işaret etmiştir.'),
  ('Rüyasında ruhunu sattığı Şeytan\'ın yatağının ucunda inanılmaz çift sesli trillerle keman çaldığını görüp uyanınca hatırladıklarını kağıda döktüğünü anlatan ve \'Il trillo del diavolo\' (Şeytan Trili) sonatıyla tanınan İtalyan virtüöz kimdir?', 'Giuseppe Tartini', ['Francesco Geminiani', 'Giovanni Battista Viotti', 'Arcangelo Corelli'], 'Padova\'da \'Ulusların Okulu\' adlı keman akademisini kuran Giuseppe Tartini (1692–1770), Sol minör \'Şeytan Trili Sonatı\'nın yanı sıra akustikte iki yüksek ses birlikte çalındığında duyulan üçüncü pes sesi (\'terzo suono\' / fark sesi) keşfetmesiyle de ünlüdür.'),
  ('18. yüzyıl başında opera başkentini Venedik\'ten Napoli\'ye taşıyan, yüzün üzerinde opera ve altı yüzü aşkın oda kantatı yazarak \'da capo arya\' ve \'İtalyan uvertürü\' kalıplarını yerleştiren Napoli okulu kurucusu kimdir?', 'Alessandro Scarlatti', ['Giovanni Paisiello', 'Muzio Clementi', 'Luigi Boccherini'], 'Domenico Scarlatti\'nin babası olan Alessandro Scarlatti (1660–1725), \'Il Mitridate Eupatore\' ve \'Griselda\' gibi ciddi operaları (opera seria) ve kromatik armonili solo kantatlarıyla Napoli ekolünün temellerini atmıştır.'),
  ('Domenico Scarlatti\'nin iki bölmeli (AABB) klavsen sonatlarını diğer Barok klavye eserlerinden hemen ayırt ettiren özgün teknik ve üslup özellikleri nelerdir?', 'Ellerin hızla birbiri üzerinden çaprazlanması, geniş sıçramalar ve İspanyol gitar/kastanyet taklitleri', ['Ayak pedallarıyla çalınan ağır kilise koralleri ve dört sesli katı ricercar kontrpuanları', 'Ölçü çizgisi bulunmayan belirsiz Fransız lavta arpejleri ve fısıltılı klavikord vibratoları', 'Yalnızca sağ elin tek parmakla ezgi çalıp sol elin şifreli bas rakamlarını doğaçlaması'], 'Scarlatti\'nin \'Essercizi\' (Alıştırmalar) adını verdiği göz kamaştırıcı sonatları; el çaprazlamaları (\'mani incrociate\'), hızlı nota tekrarları, sokak flamenkosunu andıran sert salkım akorları (acciccatura) ve akrobatik sıçramalarıyla benzersizdir.'),
  ('Domenico Scarlatti\'nin Sol minör K. 30 sonatına, klavyenin üzerinde yürüyen evcil hayvanın bastığı tuhaf ve yükselen geniş aralıklı notalardan türetildiği söylentisi nedeniyle 19. yüzyıldan itibaren hangi takma ad verilmiştir?', 'Kedi Fügü', ['Guguk Kuşu Tokatası', 'Tavuk Rondosu', 'Kelebekler Süiti'], 'Efsaneye göre Scarlatti\'nin kedisi Pulcinella klavsen tuşlarında yürürken tuhaf eksiltilmiş aralıklarla yükselen altı notalık bir dizi üretmiş; Scarlatti de bu cüretkâr özneyi usta işi bir füge dönüştürmüştür.'),
  ('Yirmi altı yaşında veremden hayatını kaybetmeden kısa süre önce Napoli\'de ciddi bir operanın perde aralarında eğlendirici \'intermezzo\' olarak sahnelenen \'La serva padrona\' (Hanım Olan Hizmetçi, 1733) ile komik operanın (opera buffa) çığırını açan besteci kimdir?', 'Giovanni Battista Pergolesi', ['Niccolò Jommelli', 'Tommaso Traetta', 'Domenico Cimarosa'], 'Kurnaz hizmetçi Serpina\'nın yaşlı efendisi Uberto\'yu kendisiyle evlenmeye ikna ettiği iki kişilik (+ bir dilsiz uşak) \'La serva padrona\', 1752\'de Paris\'te sahnelendiğinde ünlü \'Soytarılar Kavgası\'nı (Querelle des Bouffons) ateşlemiştir.'),
  ('Pergolesi\'nin 1736 yılında ölüm döşeğindeyken bir Fransisken manastırında tamamladığı; soprano, alto, yaylılar ve sürekli bas için yazılmış on iki bölümlük dokunaklı kutsal başyapıtı hangisidir?', 'Stabat Mater', ['Noel Oratoryosu', 'Mesih Oratoryosu', 'Magnificat Kantatı'], 'Çarmıhın dibinde ağlayan Meryem Ana\'nın acısını anlatan Orta Çağ ilahisi üzerine Pergolesi\'nin yazdığı \'Stabat Mater\', 18. yüzyılda Avrupa\'da en çok basılan eser olmuş ve J. S. Bach tarafından bile Mezmur 51 (BWV 1083) olarak uyarlanmıştır.'),
  ('Jean-Baptiste Lully\'nin oyun yazarı Molière ile işbirliği yaparak tiyatro komedisini şarkı ve görkemli dans sahneleriyle kaynaştırdığı türün adı ve 1670 tarihli Osmanlı elçiliği alayından esinlenen en ünlü örneği hangisidir?', 'Comédie-ballet – Kibarlık Budalası', ['Opéra-comique – Köy Kahini', 'Tragédie lyrique – Castor ve Pollux', 'Pastorale héroïque – Acis ve Galatea'], 'Molière ve Lully\'nin \'Le Bourgeois gentilhomme\' (Kibarlık Budalası) adlı comédie-ballet eserinde yer alan görkemli \'Marche pour la cérémonie des Turcs\' (Türk Töreni Marşı), dönemin Turquerie modasının ilk zirvesidir.'),
  ('Lully\'nin şair Philippe Quinault ile birlikte İtalyan operasına ulusal bir alternatif olarak yarattığı beş perdelik ciddi Fransız operası türü (\'tragédie en musique\'), İtalyan operasından hangi yönüyle belirgin biçimde ayrılır?', 'Kuru resitatif yerine Fransız şiir prozodi ritmine uyan esnek resitatifler ile zengin koro ve bale sahnelerine yer vermesi', ['Sahnede hiçbir dekor kullanmadan bütün rolleri İtalyan kastrato şarkıcılara paylaştırması', 'Bütün aryaları on dakikalık gösterişli koloratur doğaçlamalarına dayandırması', 'Orkestradan üflemeli ve yaylı çalgıları çıkarıp yalnızca solo klavsen kullanması'], 'Fransız zevki İtalyanların yapay bulduğu kastrato seslerini ve kopuk \'secco\' resitatiflerini reddetmiş; \'Cadmus et Hermione\', \'Atys\' ve \'Armide\' gibi eserlerde Fransız tiyatrosu diksiyonunu, görkemli koroları ve saray balesini kaynaştırmıştır.'),
  ('XIV. Louis sarayının ünlü yaylı orkestrası \'Les Vingt-quatre Violons du Roi\' (Kralın Yirmi Dört Kemanı), Lully\'nin katı disiplini altında Avrupa orkestra tarihine hangi icra yeniliğini kazandırmıştır?', 'Bütün yaylı çalgıcıların yay çekiş yönlerini (aşağı-yukarı) ve süslemeleri tek vücut halinde eşzamanlı uygulamasını', ['Her kemancının sahnede doğaçlama yaparak diğerlerinden farklı bir ezgi çalmasını', 'Kemanların omuz yerine diz üstünde dikey tutularak çello gibi çalınmasını', 'Yaylı grubunun ortasına dört adet kuyruklu piyano yerleştirilmesini'], 'Lully rastgele doğaçlamaları yasaklamış ve \'tek tip yay disiplini\'ni (coup d\'archet) kurarak modern senfoni orkestrası disiplininin ilk modelini yaratmıştır; Avrupa\'nın dört bir yanından müzisyenler bunu öğrenmeye Paris\'e gelmiştir.'),
  ('Fransız org ve klavsen hanedanının en parlak üyesi olduğu için \'Le Grand\' (Büyük) unvanıyla anılan, 27 klavsen süiti (\'Ordres\') ve \'L\'Art de toucher le clavecin\' (Klavsen Çalma Sanatı, 1716) adlı pedagojik kitabıyla Bach\'ı da etkileyen besteci kimdir?', 'François Couperin', ['Jean-Henri d\'Anglebert', 'Jacques Champion de Chambonnières', 'Louis-Claude Daquin'], 'François Couperin (1668–1733), klavsen parçalarına standart dans adları yerine \'Les Barricades Mystérieuses\' (Gizemli Barikatlar) ve \'Le Tic-Toc-Choc\' gibi şiirsel/portre başlıklar koymuş ve parmak numaralama tekniğini yenilemiştir.'),
  ('François Couperin\'in \'Les Goûts-réunis\' (Birleşmiş Zevkler, 1724) ile \'L\'Apothéose de Corelli\' ve \'L\'Apothéose de Lully\' adlı oda müziği eserlerinin arkasındaki estetik ideal nedir?', 'İtalyan müziğinin tutkulu virtüöz enerjisi ile Fransız müziğinin zarif dans ve süsleme inceliğini uzlaştırmak', ['Alman kilise fügünü tamamen ortadan kaldırıp yerine Osmanlı mehter ritimlerini koymak', 'Sözlü müziği yasaklayarak bütün kilise ayinlerini yalnızca solo klavsenle yürütmek', 'Orta Çağ\'ın paralel organum tınılarını modern yaylı dörtlüsüyle yeniden canlandırmak'], 'Barok çağ boyunca Avrupa\'yı ikiye bölen \'İtalyan stili mi, Fransız stili mi?\' tartışmasına Couperin (ve Almanya\'da Bach ile Telemann), her iki ulusal üslubun en iyi yönlerini kaynaştıran \'birleşmiş zevk\' ile yanıt vermiştir.'),
  ('Rameau\'nun 1735 tarihli \'Les Indes galantes\' (Zarif/Aşık Hintliler) adlı eseri; Türkiye, İnka Peru\'su, İran ve Kuzey Amerika yerlileri gibi egzotik coğrafyalarda geçen bağımsız aşk öykülerini dansla birleştiren hangi Fransız türünün başyapıtıdır?', 'Opéra-ballet', ['Singspiel', 'Oratorio volgare', 'Zarzuela'], 'André Campra\'nın başlattığı ve Rameau\'nun \'Les Indes galantes\' (özellikle ünlü \'Vahşilerin Dansı\' bölümüyle) zirveye çıkardığı opéra-ballet, her perdesinde ayrı bir öykü ve bol miktarda görkemli dans sunar.'),
  ('Rameau\'nun klavsen parçaları arasında tekrarlanan notalarla gıdaklayan bir kümes hayvanını son derece gerçekçi biçimde betimleyen ve daha sonra Respighi\'nin \'Kuşlar\' süitine de aldığı ünlü karakter parçası hangisidir?', 'La Poule', ['Le Coucou', 'L\'Abeille', 'Le Cygne'], 'Rameau, Sol minör \'La Poule\' (Tavuk) adlı klavsen parçasında partisyonun üstüne \'co-co-co-co-co-co-dai\' hecelerini bile yazarak keskin mordent ve nota tekrarlarıyla unutulmaz bir Barok tını resmi çizmiştir.'),
  ('Purcell\'in \'Dido and Aeneas\' operasının sonunda Kraliçe Dido\'nun intihar etmeden önce seslendirdiği \'When I am laid in earth\' (Toprağa konulduğumda / Beni hatırla) aryasının sarsıcı müzikal gücü hangi yapısal tekniğe dayanır?', 'Beş ölçülük kromatik alçalan sabit bir ağıt bası (ground bass) üzerinde vokal çizginin ölçü çizgilerini aşarak özgürce süzülmesine', ['Üç trompet ve timpaninin her dize sonunda cenaze topu atışlarını taklit eden gür akorlarına', 'Koro ve solistin hızlı bir İtalyan tarantella ritmiyle karşılıklı soru-cevap atışmasına', 'Şarkıcının eşliksiz tiz bölgede iki dakika süren gösterişli koloratur kadansı yapmasına'], 'Dido\'nun Ağıtı\'nda yaylılar beş ölçülük kromatik \'lamento bass\' kalıbını on bir kez amansız bir kader gibi tekrarlarken, Dido\'nun \'Remember me!\' yakarışı beş ölçülük kalıpla asimetrik örtüşerek eşsiz bir trajedi yaratır.'),
  ('17. yüzyıl sonu Londra sahnelerinde halk konuşmalı tiyatroyu tercih ettiği için Purcell\'in \'The Fairy-Queen\' (Shakespeare uyarlaması) ve \'King Arthur\' (John Dryden metni) gibi başyapıtlarını yazdığı türe ne ad verilir?', 'Yarı-opera', ['Opera seria', 'Tragédie lyrique', 'Madrigal komedisi'], 'İngiliz \'semi-opera\' (dramatick opera) türünde asıl başrol oyuncuları şarkı söylemeyip konuşmalı tiyatro oynar; Purcell\'in muhteşem müzikleri ise periler, ruhlar, çobanlar ve büyü sahnelerindeki \'masque\' bölmelerinde duyulur.'),
  ('Henry Purcell\'in 1695\'te \'Abdelazar\' (Mağripli\'nin İntikamı) adlı tiyatro oyunu için yazdığı görkemli Re minör \'Rondeau\' teması, 20. yüzyılda Benjamin Britten\'ın hangi ünlü orkestra eğitimi eserinin ana teması olmuştur?', 'Gençler İçin Orkestra Rehberi', ['Savaş Requiem\'i', 'Basit Senfoni', 'Peter Grimes Deniz Ara Oyunları'], 'Britten 1946 tarihli \'The Young Person\'s Guide to the Orchestra\' (Purcell\'in Bir Teması Üzerine Çeşitlemeler ve Füg) eserinde Abdelazar Rondeau\'sunu orkestranın tüm çalgı ailelerini tanıtmak için kullanmıştır.'),
  ('Heinrich Schütz\'ün Dresden sarayında Otuz Yıl Savaşları (1618–1648) sırasında yazdığı \'Kleine geistliche Konzerte\' (Küçük Kutsal Konçertolar, 1636/1639) eserlerini yalnızca bir ila beş solist ve sürekli bas gibi çok küçük kadroyla bestelemesinin tarihsel nedeni nedir?', 'Yıkıcı savaş, veba ve mali çöküş yüzünden Dresden saray orkestrasının ve korosunun dağılmış olması', ['Lutherci kilisenin ikiden fazla çalgının aynı anda kullanılmasını günah ilan etmesi', 'Bestecinin kalabalık orkestra tınısından nefret edip yalnızca ev müziğine yönelmesi', 'Kiliselerin kubbelerinin küçük olması nedeniyle büyük toplulukların sığmaması'], 'Otuz Yıl Savaşları\'nın Almanya\'da yarattığı büyük yıkım saray kadrolarını eritince Schütz, zorunluluğu sanata dönüştürerek az sayıda sesle olağanüstü yoğunlukta kutsal oda konçertoları yaratmıştır.'),
  ('Kuzey Almanya\'nın Hansa kenti Lübeck\'teki Marienkirche\'nin kırk yıl boyunca ünlü orgcusu olan ve Noel öncesi beş pazar akşamı düzenlediği halka açık görkemli \'Abendmusiken\' (Akşam Müzikleri) konserleriyle tanınan Danimarka-Alman usta kimdir?', 'Dietrich Buxtehude', ['Vincent Lübeck', 'Nicolaus Bruhns', 'Jan Pieterszoon Sweelinck'], 'Dietrich Buxtehude (yaklaşık 1637–1707), \'stylus phantasticus\' üslubundaki dev pedal sololu org prelüdleri, \'Membra Jesu Nostri\' kantat çevrimi ve ticaret loncalarının desteklediği Abendmusiken konserleriyle Kuzey Alman ekolünün zirvesidir.'),
  ('1678 yılında açılan ve İtalya dışında Almanya\'nın \'ilk halka açık daimi belediye opera evi\' olan Oper am Gänsemarkt (Kaz Pazarı Operası) hangi Kuzey Alman ticaret kentinde kurulmuş ve Reinhard Keiser, genç Handel ve Telemann\'a sahne olmuştur?', 'Hamburg', ['Münih Saray Merkezi', 'Salzburg Başpiskoposluğu', 'Weimar Dükalığı'], 'Özgür ticaret şehri Hamburg\'daki Gänsemarkt Operası bir prens sarayına değil kent burjuvazisine aitti; Reinhard Keiser yönetiminde gelişen bu sahnede 18 yaşındaki Handel orkestrada ikinci keman ve klavsen çalarak ilk operası \'Almira\'yı sahnelemiştir.'),
  ('1725 yılında Viyana\'da yayımladığı Latince diyalog kitabı \'Gradus ad Parnassum\' (Parnassos\'a Basamaklar) ile Palestrina tarzı kontrpuan eğitimini beş \'tür\' (species) halinde sistemleştiren ve Bach\'tan Mozart, Haydn ve Beethoven\'a dek tüm ustaların çalıştığı kuramcı-besteci kimdir?', 'Johann Joseph Fux', ['Johann Mattheson', 'Friedrich Wilhelm Marpurg', 'Johann Joachim Quantz'], 'Viyana İmparatorluk saray başmüzisyeni Johann Joseph Fux (1660–1741), \'Aloysius\' (Palestrina) ile öğrenci \'Josephus\' arasındaki diyalog biçiminde yazdığı bu kitapla yüzyıllar süren kontrpuan pedagojisini kurmuştur.'),
  ('Johann Sebastian Bach\'ın (1685–1750) meslek yaşamı boyunca görev yaptığı merkezler ve o dönemlerde odaklandığı başlıca müzik türleri eşleştirmelerinden hangisi doğrudur?', 'Weimar\'da org eserleri, Köthen\'de dünyevi orkestra/oda ve klavye müziği, Leipzig\'de ise kilise kantatları ve pasyonlar', ['Londra\'da İtalyan operaları, Paris\'te saray baleleri, Viyana\'da klasik yaylı dörtlüleri', 'Venedik\'te kızlar korosu konçertoları, Madrid\'de gitar sonatları, Roma\'da papalık ayinleri', 'Leipzig\'de komik operalar, Weimar\'da askeri bandolar, Köthen\'de eşliksiz Gregoryen ilahileri'], 'Bach\'ın üretimini çalıştığı görevin gereksinimleri şekillendirmiştir: Arnstadt/Weimar\'da saray orgcusu (org başyapıtları), Kalvinist Prens Leopold\'ün Köthen sarayında Kapellmeister (Brandenburg, süitler, İyi Düzenlenmiş Klavye I) ve 1723–1750 arası Leipzig\'de Thomaskantor (kantatlar, pasyonlar).'),
  ('Johann Sebastian Bach\'ın tüm eserlerini kronolojik olarak değil, türlerine göre (kantatlar, motetler, org eserleri, klavye eserleri vb.) numaralandıran standart \'BWV\' kataloğu hangi müzikolog tarafından hazırlanmıştır ve neyin kısaltmasıdır?', 'Wolfgang Schmieder – Bach-Werke-Verzeichnis', ['Ludwig von Köchel – Berliner-Werke-Verzeichnis', 'Otto Erich Deutsch – Barock-Welt-Verzeichnis', 'Anthony van Hoboken – Bonner-Werke-Verzeichnis'], '1950\'de (Bach\'ın ölümünün 200. yılında) Wolfgang Schmieder\'in yayımladığı \'Bach-Werke-Verzeichnis\' (Bach Eserleri Kataloğu), BWV 1\'den başlayarak tematik gruplama yöntemi kullanır.'),
  ('Bach\'ın 1721 yılında Prusya\'daki Brandenburg-Schwedt Uçbeyi Christian Ludwig\'e özenli bir el yazmasıyla ithaf ettiği altı orkestra eseri (\'Brandenburg Konçertoları\', BWV 1046–1051) çalgılama açısından neden eşsizdir?', 'Altı konçertonun her birinin birbirinden tamamen farklı ve sıra dışı çalgı kombinasyonları için yazılmış olmasıyla', ['Altısının da yalnızca tek bir solo keman ve dört sesli yaylı eşliği için tekdüze kurulmasıyla', 'Orkestrada hiç yaylı çalgı kullanmayıp yalnızca askeri bakır üflemelilere yer vermesiyle', 'Bütün konçertoların ortasında dört sesli kilise korosu ve org soloları bulundurmasıyla'], 'Bach, concertino kavramını her konçertoda yeniden icat etmiştir: 1.\'de korno-obualar-violino piccolo; 2.\'de trompet-blokflüt-obua-keman; 3.\'de 9 solo yaylı; 4.\'de keman ve 2 blokflüt; 5.\'de flüt-keman-klavsen; 6.\'da kemansız alt yaylılar!'),
  ('Bach\'ın \'5. Brandenburg Konçertosu\' (Re majör, BWV 1050), birinci bölümünün sonuna doğru gerçekleşen hangi sıra dışı olay sayesinde müzik tarihinde \'ilk klavye konçertosu\' kabul edilir?', 'Eşlikçi sanılan klavsenin giderek öne çıkıp tüm orkestrayı susturarak altmış beş ölçülük dev bir solo kadans çalmasıyla', ['Klavsenin ortadan kaldırılıp yerine yeni icat edilen kuyruklu piyanonun sahneye getirilmesiyle', 'Solist kemancının yayını bırakıp klavsenciyle birlikte dört el klavye çalmaya başlamasıyla', 'Sürekli bas partisindeki viyolonselin klavsenin üstüne çıkarak tiz ezgiyi devralmasıyla'], 'Köthen sarayına Berlin\'den yeni alınan iki klavyeli Mietke klavsenini kutlamak üzere yazılan eserde klavsen, alçakgönüllü basso continuo rolünden sıyrılıp baş döndürücü solo kadansıyla konçerto kahramanına dönüşür.'),
  ('Bach\'ın Köthen\'de 1720 yılında tamamladığı \'Solo Keman İçin Sonatlar ve Partitalar\' (BWV 1001–1006) içindeki 2. Re minör Partita\'nın son bölümü olan ve tek bir kemandan devasa bir katedral polifonisi çıkaran 257 ölçülük anıt hangisidir?', 'Chaconne', ['Siciliana', 'Loure', 'Fugato'], 'Johannes Brahms\'ın \'Küçük bir çalgı için koca bir ruh dünyası yazılmış!\' diyerek hayranlıkla sol el piyanoya da uyarladığı Re minör Chaconne, keman edebiyatının en yüce zirvesi sayılır ve çoğu araştırmacıya göre Bach\'ın ilk eşi Maria Barbara\'nın ani ölümüyle ilişkilidir.'),
  ('Bach\'ın ikinci eşi için derlediği 1725 tarihli \'Anna Magdalena Bach\'ın Nota Defteri\'nde yer alan, 20. yüzyıla dek Bach\'ın kendisinin yazdığı sanılan ancak araştırmalarla Dresdenli besteci Christian Petzold\'a ait olduğu kanıtlanan çok ünlü başlangıç parçası hangisidir?', 'Sol Majör Menuet', ['Do Majör Birinci Prelüd', 'İtalyan Konçertosu', 'Kromatik Fantazi ve Füg'], 'Aile içi ev müziği defteri olan Anna Magdalena Defteri\'ne öğrenme amacıyla başka bestecilerin parçaları da imzasız kopyalanmıştı; dünyaca ünlü Sol majör ve Sol minör Menuet ikilisinin (BWV Anh. 114–115) aslında Christian Petzold\'un bir klavsen süitinden alındığı 1970\'lerde saptanmıştır.'),
  ('Bach\'ın 1741\'de yayımladığı otuz çeşitlemelik klavsen başyapıtı \'Goldberg Çeşitlemeleri\'ne (BWV 988) ilişkin ünlü öyküye göre eserin yazılış vesilesi ve adını aldığı kişi kimdir?', 'Uykusuzluk çeken Rus Elçisi Kont Keyserlingk\'i geceleri dinlendirmek üzere genç klavsencisi Johann Gottlieb Goldberg\'in çalması', ['Prusya Kralı Büyük Friedrich\'in altın kaplamalı saray piyanosunun açılış töreninde bizzat çalması', 'Nürnbergli altın varak ustası Johann Goldberg\'in Bach\'ın portresini yapmasına karşılık hediye edilmesi', 'Londra\'daki Altın Taç Tiyatrosu\'nun klavsen yarışmasında birinci gelecek öğrenciyi seçmek için yazılması'], 'İlk Bach biyografisi yazarı Forkel\'in aktardığı geleneğe göre Dresden\'deki Rus elçisi Kont Keyserlingk uykusuz gecelerinde genç virtüözü Goldberg\'e \'Bana çeşitlemelerimden birini çal\' derdi; eserin kusursuz matematiksel mimarisi (her 3. çeşitlemede büyüyen kanonlar: ünisondan dokuzluya!) eşsizdir.'),
  ('Bach\'ın son yıllarında (1747) Potsdam sarayını ziyaret ettiğinde Prusya Kralı II. Friedrich\'in (Büyük Friedrich) klavyede çaldığı zorlu ve kromatik \'Kraliyet Teması\' (Thema Regium) üzerine doğaçlayıp Leipzig\'e dönünce basarak Kral\'a sunduğu eser hangisidir?', 'Müzikal Sunu', ['Füg Sanatı', 'Altı Partita', 'Fransız Süitleri'], '\'Musikalisches Opfer\' (Müzikal Sunu, BWV 1079), Kral\'ın verdiği temadan üretilen üç sesli ve altı sesli iki muhteşem \'Ricercar\', çeşitli bilmeceli kanonlar ve Kral\'ın çok sevdiği yan flütü onurlandıran dört bölümlü bir Trio Sonat içerir.'),
  ('Alman nota harf adlandırma sisteminde J. S. Bach\'ın kendi soyadını müzikal imza olarak kullandığı ünlü \'B–A–C–H\' dört nota motifi, standart solfej sesleriyle hangi perdelere karşılık gelir?', 'Si bemol – La – Do – Si naturel', ['Si naturel – La – Do diyez – Sol', 'Re – La – Do – Fa diyez', 'Mi bemol – Do – Sol – Si bemol'], 'Alman sisteminde \'B\' harfi Si bemol, \'A\' harfi La, \'C\' harfi Do ve \'H\' harfi Si naturel sesini gösterir; bu dar ve dokunaklı kromatik kıvrım (B–A–C–H), Bach\'tan Liszt, Schumann ve Şostakoviç\'e dek sayısız eserde saygı motifi olmuştur.'),
  ('Bach\'ın 1727\'de Leipzig\'de ilk kez seslendirdiği anıtsal \'Matta Pasyonu\'nun (Matthäus-Passion, BWV 244) mekansal ve işitsel etkisini iki katına çıkaran görkemli topluluk düzeni nasıldır?', 'İki ayrı koro, iki ayrı orkestra ve ek bir çocuk korosunun (ripieno) karşılıklı diyalog kuracak biçimde yerleştirilmesi', ['Sahnede yalnızca dört solist ve tek bir taşınabilir org ile oda müziği boyutunda çalınması', 'Bütün cemaatin ellerindeki çanları sallayarak orkestraya ritmik eşlik etmesi', 'Yalnızca bakır üflemeliler ve erkekler korosu için açık meydanda seslendirilmesi'], 'Matta Pasyonu\'nun 12/8\'lik dev açılış korosu \'Kommt, ihr Töchter, helft mir klagen\'da Koro I ve Koro II karşılıklı \'Kimi? – Güveyi! Nasıl? – Bir kuzu gibi!\' sorularıyla atışırken üstten üçüncü bir soprano korosu \'O Lamm Gottes, unschuldig\' koralini taç gibi örer.'),
  ('12. yüzyılda Paris\'teki Notre Dame Okulu temsilcileri Léonin ve Pérotin\'in Batı müzik tarihine yaptıkları en önemli katkı hangisidir?', 'Ölçülü ritmik kalıplarla üç ve dört sesli organum yazısını geliştirmeleri', ['Majör ve minör dizi sistemini kuramsal olarak kesinleştirmeleri', 'İlk kez bakır üflemeli çalgıları kilise ayinlerine dâhil etmeleri', 'Şarkı sözlerinde Latince yerine yalnızca yerel halk dilini kullanmaları'], 'Léonin ve Pérotin, Gregoryen ezgilerinin üzerine eklenen sesleri ritmik modlarla örgütleyerek çok sesli müziğin (polifoni) ilk büyük mimari örneklerini vermiştir.'),
  ('14. yüzyıl Fransız müziğindeki "Ars Nova" (Yeni Sanat) akımını önceki "Ars Antiqua" döneminden ayıran temel yenilik nedir?', 'Üçlü ritmik bölünmenin yanında ikili bölünmeye de eşit statü tanınması', ['Vokal müziğin tamamen terk edilerek yalnızca çalgı müziğine yönelinmesi', 'Nota yazımında dizek çizgilerinin kaldırılıp harf tabulatürüne geçilmesi', 'Kilise modlarının yerine on iki tonlu kromatik dizinin benimsenmesi'], 'Philippe de Vitry\'nin risalesinden adını alan Ars Nova, yalnız "mükemmel" sayılan üçlü zamanı değil, "kusurlu" sayılan ikili zaman bölünmesini ve senkoplu izoritmik yapıları meşrulaştırmıştır.'),
  ('Orta Çağ\'da hem kadın hem erkek seslerinin sınırlarını aşan mistik ilahileri ve "Ordo Virtutum" adlı ahlak oyunuyla tanınan 12. yüzyıl başrahibesi kimdir?', 'Hildegard von Bingen', ['Beatriz de Dia', 'Kassia', 'Francesca Caccini'], 'Alman benedikten başrahibesi Hildegard von Bingen, geniş ses aralıklı monofonik ilahileri ve bilinen en eski müzikli ahlak dramı "Ordo Virtutum" ile tanınır.'),
  ('14. yüzyılda tüm olağan bölümleri (Kyrie, Gloria, Credo, Sanctus, Agnus Dei) tek bir besteci tarafından bütünlüklü olarak çok sesli yazılmış ilk Missa örneği olan "Messe de Nostre Dame" kime aittir?', 'Guillaume de Machaut', ['Guillaume Dufay', 'Johannes Ockeghem', 'John Dunstable'], 'Fransız şair ve besteci Guillaume de Machaut\'nun dört sesli "Messe de Nostre Dame" yapıtı, ayinin beş temel bölümünü tek elden birleştiren ilk eksiksiz polifonik missadır.'),
  ('Orta Çağ ve Rönesans çok sesli müziğinde, mevcut bir Gregoryen ezgisinin veya halk şarkısının uzun notalarla temel alınarak üzerine yeni kontrpuan sesleri örülmesi tekniğine ne denir?', 'Cantus firmus tekniği', ['Şifreli bas uygulaması', 'Ritornello formu', 'Alberti bası eşliği'], '"Sabit ezgi" anlamına gelen cantus firmus, genellikle tenor partisinde uzun sürelerle duyurulur ve diğer seslerin etrafında şekillendiği yapısal omurgayı oluşturur.'),
  ('Rönesans madrigallerinde metinde "yükselmek" kelimesi geçerken ezginin tizleşmesi, "iç çekmek" ifadesinde ise kısa suslarla bölünmesi hangi estetik anlayışı örneklendirir?', 'Söz boyama', ['İzoritmik motet kurgusu', 'Sürekli bas doğaçlaması', 'Eşit tamperaman akordu'], 'Söz boyama (word painting / madrigalism), şiirdeki imgelerin ve duygusal kavramların doğrudan müzikal hareketlerle somutlaştırılması tekniğidir.'),
  ('Venedik\'teki San Marco Bazilikası\'nda Andrea ve Giovanni Gabrieli\'nin karşılıklı balkonlara yerleştirilmiş birden fazla koro ve çalgı grubuyla geliştirdikleri üslup hangisidir?', 'Kori spezzati', ['Stile rappresentativo', 'Notre Dame organumu', 'Burgonya şanson okulu'], 'San Marco\'nun geniş mimarisinden yararlanan "cori spezzati" (polikoral üslup), mekânsal yankılanma ve gürlük karşıtlıklarıyla Barok konçerto fikrine zemin hazırlamıştır.'),
  ('Claudio Monteverdi, eleştirmen Artusi ile girdiği tartışmada sözün müziğe hâkim olduğu ve hazırlıksız uyumsuzluklara (disonanslara) izin veren yeni Barok yaklaşımı nasıl adlandırmıştır?', 'Seconda pratica (İkinci uygulama)', ['Prima pratica (Birinci uygulama)', 'Ars subtilior (İncelikli sanat)', 'Musica ficta (Kurgu müzik)'], 'Monteverdi, Palestrina tarzı katı kontrpuan kurallarını "prima pratica", metnin duygusal ifadesi uğruna armonik kuralları esneten yeni dramatik üslubu ise "seconda pratica" olarak tanımlamıştır.'),
  ('Barok konçerto grosso formunda küçük solistler grubu ile büyük orkestra topluluğu arasındaki yapısal iş bölümü hangi terim çiftiyle ifade edilir?', 'Concertino ve Ripieno', ['Soggetto ve Risposta', 'Dux ve Comes', 'Antifon ve Responsorium'], 'Konçerto grossoda birkaç solistten oluşan küçük gruba "concertino", tüm orkestrayı kapsayan eşlik ve tutti topluluğuna ise "ripieno" (veya concerto grosso) adı verilir.'),
  ('Bir Barok fügün sergi (ekspozisyon) bölümünde ana temayı (suje) Do majör tonunda duyuran ilk sesten sonra giren ikinci ses, kurala uygun "cevap" (comes) partisini hangi tonda başlatır?', 'Sol majör (çeken tonu)', ['Fa majör (altçeken tonu)', 'La minör (ilgili minör tonu)', 'Do minör (adaş minör tonu)'], 'Geleneksel füg kurgusunda ana tonda (tonik) sunulan sujeye verilen cevap (answer/comes), tam beşli yukarıdaki çeken (dominant) tonunda yani Sol majörde girer.'),
  ('Bir fügün ilerleyen kesitlerinde gerginliği artırmak amacıyla, birinci ses temayı henüz bitirmeden diğer seslerin aynı temayla sıkışık aralıklarla peş peşe girmesine ne ad verilir?', 'Stretto', ['Pedal noktası', 'Koda', 'Epizod'], '"Daraltma, sıkıştırma" anlamına gelen stretto, füg temasının (suje) üst üste bindirilerek kanonik biçimde sıklaştırılmasıyla doruk noktası yaratan tekniktir.'),
  ('George Frideric Handel\'in Londra halkının İtalyan operasına ilgisinin azalması üzerine geliştirdiği İngilizce oratoryo geleneğinin toplumsal başarısını açıklayan temel etken nedir?', 'Orta sınıf dinleyicinin ana dilde anladığı Eski Ahit öykülerini koro görkemiyle sunması', ['Yalnızca saray mensuplarının katılabildiği kapalı salonlarda ücretsiz icra edilmesi', 'Orkestrayı tamamen kaldırarak yalnızca org eşliğinde küçük korolar kullanması', 'Sahne üzerinde karmaşık barok makineler ve bale gösterilerine ağırlık vermesi'], 'Handel, pahalı İtalyan kastrato şarkıcılarına dayalı opera seria yerine İngilizce metinli ve görkemli korolara sahip oratoryolar yazarak yükselen İngiliz orta sınıfını kazanmıştır.'),
  ('George Frideric Handel\'in Mısır\'a gönderilen on belayı koro tasvirleriyle betimlediği ve olağan dışı biçimde koro bölümlerinin solist aryalardan çok daha ağırlıklı olduğu oratoryosu hangisidir?', 'İsrail Mısır\'da', ['Judas Maccabaeus', 'Samson', 'Solomon'], '1739 tarihli "Israel in Egypt", kurbağa sıçrayışlarından dolu fırtınasına ve Kızıldeniz\'in yarılmasına kadar olayları çift korolu çarpıcı ses betimlemeleriyle anlatan özgün bir Handel oratoryosudur.'),
  ('Yaşadığı dönemde Almanya\'da Bach\'tan bile daha geniş şöhrete sahip olan, dört binden fazla eser veren ve "Tafelmusik" (Sofra Müziği) koleksiyonuyla tanınan Barok besteci kimdir?', 'Georg Philipp Telemann', ['Johann Pachelbel', 'Dietrich Buxtehude', 'Johann Joachim Quantz'], 'Çok yönlü ve üretken bir besteci olan Telemann, 1733\'te yayımladığı üç ciltlik "Musique de Table" (Tafelmusik) koleksiyonunda üvertür-süit, konçerto, kuartet ve sonat formlarını birleştirmiştir.'),
  ('Georg Philipp Telemann\'ın o dönemde genellikle eşlik partisi çalan bir yaylı çalgıyı solist konumuna yükselttiği ve türünün bilinen ilk büyük örneği sayılan Sol majör eseri hangisidir?', 'Viyola Konçertosu', ['Kontrbas Sonatı', 'Baryton Süiti', 'Trombon Konçertosu'], 'Telemann\'ın dört bölümlü Sol majör Viyola Konçertosu (TWV 51:G9), viyola için bestelenmiş bilinen ilk solo konçerto olarak standart repertuvarda önemli yer tutar.'),
  ('Jean-Philippe Rameau\'nun 1722\'de yayımladığı "Traité de l\'harmonie" (Armoni İncelemesi) adlı kuramsal eseri müzik teorisinde hangi köklü değişimi başlatmıştır?', 'Akorların çevrim (inversiyon) kavramını ve temel bas (basse fondamentale) ilkesini sistemleştirmesi', ['On iki eşit yarım tondan oluşan dizide tonal merkezi tamamen ortadan kaldırması', 'Orta Çağ kilise modlarının modern orkestra müziğinde zorunlu tutulmasını savunması', 'Yaylı çalgıların akordunda doğal doğuşkanlar yerine elektronik ölçüm önermesi'], 'Rameau, bir akorun sesleri yer değiştirse bile kök sesinin (basse fondamentale) kimliğini koruduğunu ortaya koyarak modern fonksiyonel armoni kuramının kurucusu olmuştur.'),
  ('Jean-Philippe Rameau\'nun egzotik ülkelerde geçen aşk öykülerini işlediği "Les Indes galantes" (Zarif Hintliler) adlı sahne eseri Fransız Barok geleneğindeki hangi türün en parlak örneğidir?', 'Opéra-ballet', ['Tragédie en musique', 'Intermezzo', 'Singspiel'], 'Osmanlı, İran, Peru ve Kuzey Amerika sahneleri içeren "Les Indes galantes", her perdesi bağımsız bir öykü anlatan ve dansın ön planda olduğu Fransız "opéra-ballet" türünün başyapıtıdır.'),
  ('François Couperin\'in klavsen kitaplarını geleneksel süit adı yerine hangi terimle gruplandırdığı ve içindeki parçaları nasıl biçimlendirdiği doğrudur?', '"Ordre" adı altında şiirsel ve betimleyici başlıklı karakter parçaları olarak', ['"Ricercar" adı altında yalnızca soyut matematiksel kanon dizileri olarak', '"Sinfonia" adı altında üç bölümlü İtalyan üvertürü şablonuna bağlı kalarak', '"Partita" adı altında Protestan kilise korallerinin çeşitlemeleri olarak'], 'Couperin, klavsen parçalarını 27 "Ordre" içinde toplamış; "Gizemli Barikatlar" (Les Barricades mystérieuses) veya "Kelebekler" gibi zarif portre ve karakter başlıkları kullanmıştır.'),
  ('Domenico Scarlatti\'nin İspanya ve Portekiz saraylarındaki yaşamının klavsen sonatlarına yansıyan en belirgin üslup özelliği hangisidir?', 'Flamenko gitarını andıran keskin akor tekrarları, el çaprazlamaları ve geniş sıçramalar', ['Alman Protestan korallerinden alınan ağır ve dört sesli kontrpuan dokusu', 'Fransız saray balelerinden uyarlanan noktalı ritimli ağırbaşlı üvertür girişleri', 'İngiliz halk şarkılarına dayanan sade ve süslemesiz tek sesli ezgi çizgileri'], 'İber Yarımadası\'nda uzun yıllar geçiren Scarlatti, sonatlarında İspanyol gitarının "rasgueado" (tüm tellere vurma) tekniğini taklit eden çarpıcı disonanslar ve virtüöz el çaprazlamaları kullanmıştır.'),
  ('Antonio Vivaldi konçertolarının hızlı bölümlerinde orkestranın ana temayı farklı tonlarda yinelediği, solistin ise bu bölmeler arasında virtüöz pasajlar çaldığı form hangisidir?', 'Ritornello formu', ['Sonat-allegro formu', 'Da capo arya formu', 'Kanonik varyasyon formu'], 'Vivaldi ile özdeşleşen ritornello formunda tüm orkestranın (tutti) çaldığı "ritornello" bölmesi çeşitli tonlarda geri dönerken aradaki solo "epizod" kesitleri modülasyon ve ustalık sergiler.'),
  ('Barok opera seria ve oratoryolarda "A - B - A" şemasıyla kurgulanan "Da capo arya" formunda, baştaki A bölümünün ikinci kez seslendirilişi sırasında solistten beklenen uygulama nedir?', 'Ezgiyi kendi ustalığını gösterecek doğaçlama süslemeler ve çeşitlemelerle zenginleştirmesi', ['Metni tamamen bırakıp yalnızca orkestra şefinin işaret ettiği vokaliz hecelerini söylemesi', 'A bölümünü bir oktav daha pes seslendirerek eseri fısıltı düzeyinde sonlandırması', 'Hiçbir nota veya ritim değişikliği yapmadan ilk okuyuşu mekanik biçimde tekrarlaması'], '"Baştan" anlamına gelen "da capo" tekrarı sırasında Barok şarkıcılar, ilk kez duyurdukları A kesitinin ezgi çizgisini zarif pasajlar, triller ve doğaçlama süslerle bezeyerek yorumlardı.'),
  ('Barok süsleme sanatında esas notanın değerinden pay alarak onun önüne eklenen, vurgu taşıyan ve genellikle disonans yaratıp esas sese çözülen yaslanma notasına ne ad verilir?', 'Apajyatür (Appoggiatura)', ['Mordent', 'Arpej (Arpeggio)', 'Staccato'], 'İtalyanca "appoggiare" (yaslanmak) fiilinden gelen apajyatür, vuruşun tam üzerinde duyurulup ana notaya çözülen ve duygusal gerilim yaratan en önemli Barok süslemelerdendir.'),
  ('Barok klavye müziğinde esas notanın bir alt komşu sesle çok hızlıca tek bir kez gidip gelmesiyle yapılan ve üzerinde dikey çizgi bulunan zikzak işaretiyle gösterilen süsleme hangisidir?', 'Mordent', ['Gruppetto', 'Portamento', 'Bariolage'], 'Fransız Barok geleneğinde "pincé" olarak da bilinen mordent, ana sesin alt yardımcı notaya hızla çarpıp anında esas sese dönmesiyle keskin bir ritmik vurgu sağlar.'),
  ('Barok dönemde lavtanın bas seslerini güçlendirmek amacıyla ikinci bir sap ve perdesiz uzun bas telleri eklenerek geliştirilen, sürekli bas eşliğinde sıkça kullanılan çalgı hangisidir?', 'Teorbo', ['Mandolin', 'Vihuela', 'Rebek'], '16. yüzyıl sonlarında İtalya\'da ortaya çıkan teorbo (chitarrone), çok uzun uzatma sapındaki diyapazon bas telleriyle erken Barok opera ve oda müziğinde ideal bir continuo çalgısı olmuştur.'),
  ('Barok klavyeli çalgılardan klavikordun (clavichord) klavsenden ayrılan en önemli ses üretim ve ifade özelliği nedir?', 'Tuşa bağlı pirinç teğetin tele dokunmasıyla çalışması ve parmak basıncıyla nüans ile vibrato (Bebung) yapılabilmesi', ['Üç katlı klavyeye ve ayak pedallarına sahip olduğu için büyük katedralleri dolduracak gürlükte ses vermesi', 'Tellerin keçeli büyük çekiçlerle dövülmesi sayesinde modern senfoni orkestrasıyla konçerto çalmaya uygun olması', 'Körüklerle üflenen havanın metal borulardan geçmesiyle kesintisiz ve sönümlenmeyen uzatma sesleri üretmesi'], 'Klavikord çok kısık sesli bir ev çalgısı olmasına karşın, tuş bırakılmadıkça pirinç teğet (tangent) telle teması sürdürdüğü için dokunuş hassasiyetine ve "Bebung" adı verilen vibratoya olanak tanır.'),
  ('Barok dönemde kullanılan "doğal trompet" ve "doğal korno" çalgılarının piston veya valf mekanizması bulunmaması bestecileri hangi yazım tekniğine yöneltmiştir?', 'Melodik çizgileri borunun doğal doğuşkanlar dizisindeki tiz bölgede (clarino sicili) yoğunlaştırmaya', ['Bu çalgıları yalnızca tek bir bas notasını tutan ritmik vurmalı çalgı gibi kullanmaya', 'Her ölçüde çalgıcının boruyu kesip kısaltmasını gerektiren kromatik diziler yazmaya', 'Bakır üflemeli çalgıları hiçbir zaman yaylı çalgılarla aynı eserde bir araya getirmemeye'], 'Valfsiz Barok trompetlerde tam ve yarım seslerden oluşan ezgisel hareket ancak doğuşkanların birbirine yaklaştığı tiz bölgede elde edilebildiğinden, ustalık isteyen "clarino" tekniği gelişmiştir.'),
  ('Fransız Üvertürü ile İtalyan Üvertürü (Sinfonia) arasındaki yapısal tempo dizilimi farkı hangi seçenekte doğru karşılaştırılmıştır?', 'Fransız üvertürü "Ağır (noktalı ritimli) - Hızlı (füg karakterli)", İtalyan üvertürü ise "Hızlı - Ağır - Hızlı" düzenindedir', ['Fransız üvertürü yalnızca ağır bir sarabande dansından, İtalyan üvertürü ise kesintisiz tek bir hızlı fügden oluşur', 'Fransız üvertürü "Hızlı - Ağır - Hızlı", İtalyan üvertürü ise "Ağır (noktalı ritimli) - Hızlı (kanonik)" düzenindedir', 'Her iki üvertür türü de dört bölümlü kilise sonatı (sonata da chiesa) şemasına birebir uymak zorundadır'], 'Jean-Baptiste Lully\'nin yerleştirdiği Fransız üvertürü görkemli noktalı ritimli ağır giriş ve ardından gelen taklitli hızlı kesitle tanınırken, Alessandro Scarlatti\'nin geliştirdiği İtalyan sinfoniası Hızlı-Ağır-Hızlı kurgusundadır.'),
  ('Arcangelo Corelli\'nin Barok dönemde standartlaştırdığı "Sonata da chiesa" (Kilise sonatı) ile "Sonata da camera" (Oda sonatı) arasındaki temel içerik farkı nedir?', 'Kilise sonatı genellikle "Ağır-Hızlı-Ağır-Hızlı" soyut bölümlerden, oda sonatı ise dans başlıkları taşıyan bölümlerden oluşur', ['Kilise sonatında yalnızca insan sesleri yer alırken oda sonatında yalnızca vurmalı ve üflemeli çalgılar kullanılır', 'Kilise sonatı tek bir klavsen solisti için yazılırken oda sonatı en az kırk kişilik koro gerektirir', 'Kilise sonatı İspanyol halk ezgilerine dayanırken oda sonatı Latince Gregoryen ilahilerini işler'], 'Corelli\'nin Op. 1 ve Op. 3 eserlerindeki gibi kilise sonatları ciddi ve kontrpuanlı dört bölümden (Ağır-Hızlı-Ağır-Hızlı) oluşurken, Op. 2 ve Op. 4 oda sonatları stilize dans bölümlerinden kurulu birer süittir.'),
  ('Barok dönemde tekrarlanan sabit bir bas ezgisi veya armonik yürüyüş üzerine kesintisiz çeşitlemeler inşa edilen üç zamanlı iki yakın form hangisidir?', 'Passacaglia ve Chaconne', ['Toccata ve Ricercar', 'Allemande ve Courante', 'Gavotte ve Bourrée'], 'Kökenleri İspanya ve Latin dünyasına uzanan Passacaglia ve Chaconne, üç zamanlı ağır tempoda tekrarlanan bir bas ostinatosu ya da akor dizisi üzerine kurulu görkemli çeşitleme formlarıdır.'),
  ('Barok "Trio sonat" (Üçlü sonat) türünde sahnede genellikle üç değil dört icracının yer almasının nedeni nedir?', 'İki tiz solo çalgının yanında üçüncü parti olan sürekli basın hem çello hem de klavsen/org tarafından birlikte çalınması', ['Eserin ortasında sürpriz bir vokal solistin sahneye çıkarak İtalyanca bir arya seslendirmesinin zorunlu olması', 'Nota sehpasını çevirmek ve yaylı çalgıların akordunu kontrol etmek için dördüncü bir müzisyenin eşlik etmesi', 'Birinci keman partisinin her zaman iki kemancı tarafından ünison olarak çalınması kuralının bulunması'], 'Trio sonat "üç yazılı parti" (genellikle iki keman/flüt ve basso continuo) içerir; ancak sürekli bas partisi bir bas yaylı çalgı ve bir klavyeli/telli akor çalgısıyla iki kişi tarafından seslendirilir.'),
  ('İngiliz Barok müziğinin en büyük temsilcisi Henry Purcell\'in Kartaca Kraliçesi\'nin trajik ölüm aryası "When I am laid in earth" (Dido\'nun Ağıtı) ile sonlanan ünlü operası hangisidir?', 'Dido ve Aeneas', ['Peri Kraliçesi', 'Kral Arthur', 'Orfeo ve Euridice'], 'Henry Purcell\'in Vergilius\'un "Aeneis" destanından uyarlanan "Dido ve Aeneas" (yak. 1689) operası, kromatik alçalan ostinato bas (ground bass) üzerine kurulu kapanış ağıtıyla ünlüdür.'),
];
